import React, { useState, useRef, useEffect } from "react";

// InventoryHub_ProfileComponent.jsx
// Single-file React component (Tailwind CSS classes) that provides:
// - Advanced customer loader (search + select + mock async load)
// - Company profile form (name, address)
// - Upload company logo with preview
// - Draggable & resizable logo overlay for page adjustment
// - Simple quotation builder (add items, calculate totals)

export default function InventoryHubProfile() {
  // Company/profile state
  const [companyName, setCompanyName] = useState("MY COMPANY NAME");
  const [address1, setAddress1] = useState("Plot No 123, Industrial Area");

  // Customer search / load (mock async)
  const sampleCustomers = [
    { id: 1, name: "Acme Corp", gst: "27AAAAA1111A1Z5" },
    { id: 2, name: "Beta Industries", gst: "07BBBBB2222B2Z6" },
    { id: 3, name: "Charlie Traders", gst: "09CCCCC3333C3Z7" },
    { id: 4, name: "Delta Supplies", gst: "19DDDDD4444D4Z8" },
  ];
  const [query, setQuery] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [isSearching, setIsSearching] = useState(false);

  // Debounced search simulation
  useEffect(() => {
    if (!query) {
      setSearchResults([]);
      return;
    }
    setIsSearching(true);
    const t = setTimeout(() => {
      const q = query.toLowerCase();
      const filtered = sampleCustomers.filter((c) => c.name.toLowerCase().includes(q));
      setSearchResults(filtered);
      setIsSearching(false);
    }, 300);
    return () => clearTimeout(t);
  }, [query]);

  const onSelectCustomer = (c) => {
    setSelectedCustomer(c);
    setCompanyName(c.name);
    setQuery("");
    setSearchResults([]);
  };

  // Logo upload + preview + drag & resize
  const [logoUrl, setLogoUrl] = useState(null);
  const [logoFileName, setLogoFileName] = useState(null);

  // position & size of logo overlay (px)
  const [logoState, setLogoState] = useState({ x: 30, y: 10, width: 140, height: 60 });
  const draggingRef = useRef(false);
  const resizingRef = useRef(false);
  const dragStartRef = useRef({ x: 0, y: 0, origX: 0, origY: 0 });
  const resizeStartRef = useRef({ x: 0, y: 0, origW: 0, origH: 0 });
  const containerRef = useRef(null);

  useEffect(() => {
    const onMove = (e) => {
      if (draggingRef.current) {
        e.preventDefault();
        const clientX = e.clientX ?? (e.touches && e.touches[0].clientX);
        const clientY = e.clientY ?? (e.touches && e.touches[0].clientY);
        const dx = clientX - dragStartRef.current.x;
        const dy = clientY - dragStartRef.current.y;
        setLogoState((s) => ({ ...s, x: Math.max(0, dragStartRef.current.origX + dx), y: Math.max(0, dragStartRef.current.origY + dy) }));
      }
      if (resizingRef.current) {
        e.preventDefault();
        const clientX = e.clientX ?? (e.touches && e.touches[0].clientX);
        const clientY = e.clientY ?? (e.touches && e.touches[0].clientY);
        const dx = clientX - resizeStartRef.current.x;
        const dy = clientY - resizeStartRef.current.y;
        const newW = Math.max(40, resizeStartRef.current.origW + dx);
        const newH = Math.max(24, resizeStartRef.current.origH + dy);
        setLogoState((s) => ({ ...s, width: newW, height: newH }));
      }
    };
    const onUp = () => {
      draggingRef.current = false;
      resizingRef.current = false;
    };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    window.addEventListener("touchmove", onMove, { passive: false });
    window.addEventListener("touchend", onUp);
    return () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
      window.removeEventListener("touchmove", onMove);
      window.removeEventListener("touchend", onUp);
    };
  }, []);

  const onLogoChange = (ev) => {
    const f = ev.target.files && ev.target.files[0];
    if (!f) return;
    setLogoFileName(f.name);
    const url = URL.createObjectURL(f);
    setLogoUrl(url);
  };

  const startDrag = (e) => {
    draggingRef.current = true;
    const clientX = e.clientX ?? (e.touches && e.touches[0].clientX);
    const clientY = e.clientY ?? (e.touches && e.touches[0].clientY);
    dragStartRef.current = { x: clientX, y: clientY, origX: logoState.x, origY: logoState.y };
  };

  const startResize = (e) => {
    resizingRef.current = true;
    const clientX = e.clientX ?? (e.touches && e.touches[0].clientX);
    const clientY = e.clientY ?? (e.touches && e.touches[0].clientY);
    resizeStartRef.current = { x: clientX, y: clientY, origW: logoState.width, origH: logoState.height };
  };

  const resetLogoPlacement = () => {
    setLogoState({ x: 30, y: 10, width: 140, height: 60 });
  };

  // Simple Quotation builder
  const [items, setItems] = useState([{ id: 1, name: "Item A", qty: 1, price: 100 }]);
  const addItem = () => setItems((s) => [...s, { id: Date.now(), name: "New Item", qty: 1, price: 0 }]);
  const updateItem = (id, patch) => setItems((s) => s.map((it) => (it.id === id ? { ...it, ...patch } : it)));
  const removeItem = (id) => setItems((s) => s.filter((it) => it.id !== id));

  const subtotal = items.reduce((acc, it) => acc + it.qty * it.price, 0);
  const taxRate = 0.18; // 18%
  const tax = subtotal * taxRate;
  const total = subtotal + tax;

  // Save handler (mock)
  const onSave = () => {
    const payload = {
      companyName,
      address1,
      customer: selectedCustomer,
      logoFileName,
      logoPlacement: logoState,
      quotation: { items, subtotal, tax, total },
    };
    console.log("Saving profile payload:", payload);
    alert("Profile saved (mock). Check console for payload.");
  };

  return (
    <div className="p-6 bg-slate-900 min-h-screen text-slate-100">
      <div className="max-w-5xl mx-auto bg-slate-800 rounded-2xl shadow-lg p-6">
        <header className="flex items-center justify-between mb-6">
          <h2 className="text-xl font-semibold">Profile Section — Advanced</h2>
          <div className="flex gap-3 items-center">
            <button onClick={resetLogoPlacement} className="px-3 py-1 rounded bg-slate-700 hover:bg-slate-600">Reset Logo</button>
            <button onClick={onSave} className="px-4 py-2 bg-blue-600 rounded shadow">Save</button>
          </div>
        </header>

        <div className="grid grid-cols-2 gap-6">
          {/* LEFT: Form + search */}
          <div className="space-y-4">
            <div>
              <label className="block text-sm text-slate-300 mb-1">Load Customer (advanced search)</label>
              <input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Search customers by name..."
                className="w-full p-2 rounded bg-slate-700 text-slate-100"
              />
              {isSearching && <div className="text-xs text-slate-400 mt-1">Searching...</div>}
              {searchResults.length > 0 && (
                <ul className="mt-2 bg-slate-700 rounded divide-y divide-slate-600 max-h-40 overflow-auto">
                  {searchResults.map((c) => (
                    <li key={c.id} className="p-2 hover:bg-slate-600 cursor-pointer" onClick={() => onSelectCustomer(c)}>
                      <div className="font-medium">{c.name}</div>
                      <div className="text-xs text-slate-300">GST: {c.gst}</div>
                    </li>
                  ))}
                </ul>
              )}
            </div>

            <div>
              <label className="block text-sm text-slate-300">Company Name</label>
              <input value={companyName} onChange={(e) => setCompanyName(e.target.value)} className="w-full p-2 rounded bg-slate-700" />
            </div>

            <div>
              <label className="block text-sm text-slate-300">Address Line 1</label>
              <input value={address1} onChange={(e) => setAddress1(e.target.value)} className="w-full p-2 rounded bg-slate-700" />
            </div>

            <div>
              <label className="block text-sm text-slate-300">Upload Company Logo</label>
              <div className="flex gap-2 items-center">
                <input type="file" accept="image/*" onChange={onLogoChange} className="text-sm" />
                {logoFileName && <div className="text-xs text-slate-300">{logoFileName}</div>}
              </div>
              <div className="text-xs text-slate-400 mt-1">After upload, drag to position and use the resize handle on the bottom-right.</div>
            </div>

            <div className="mt-4 border-t border-slate-700 pt-4">
              <h3 className="text-md font-semibold">Selected Customer</h3>
              {selectedCustomer ? (
                <div className="p-3 bg-slate-700 rounded mt-2">
                  <div className="font-medium">{selectedCustomer.name}</div>
                  <div className="text-xs">GST: {selectedCustomer.gst}</div>
                </div>
              ) : (
                <div className="text-slate-400 mt-2">No customer selected</div>
              )}
            </div>
          </div>

          {/* RIGHT: Preview area with logo placement + quotation builder */}
          <div>
            <div className="relative bg-slate-900 rounded p-4 h-64 overflow-hidden border border-slate-700" ref={containerRef}>
              {/* Simulated page where logo can be placed */}
              <div className="absolute left-4 top-3 text-slate-400 text-sm">Page Preview</div>

              {/* Company header text */}
              <div className="absolute left-4 top-14 text-white font-semibold text-lg">{companyName}</div>

              {/* Logo overlay */}
              {logoUrl && (
                <div
                  className="absolute cursor-grab"
                  onMouseDown={startDrag}
                  onTouchStart={startDrag}
                  style={{ left: logoState.x, top: logoState.y, width: logoState.width, height: logoState.height }}
                >
                  <img src={logoUrl} alt="logo" style={{ width: '100%', height: '100%', objectFit: 'contain', borderRadius: 6 }} />
                  {/* resize handle */}
                  <div
                    onMouseDown={startResize}
                    onTouchStart={startResize}
                    className="absolute right-0 bottom-0 w-4 h-4 bg-slate-600 cursor-se-resize rounded-tr"
                    style={{ transform: 'translate(50%, 50%)' }}
                  />
                </div>
              )}

              {/* If no logo, show placeholder */}
              {!logoUrl && (
                <div className="absolute left-4 top-14 w-36 h-16 bg-slate-700 rounded flex items-center justify-center text-slate-400">No Logo</div>
              )}

              {/* small guidance */}
              <div className="absolute right-3 bottom-3 text-xs text-slate-400">Drag logo to position • Resize using handle</div>
            </div>

            {/* Quotation builder */}
            <div className="mt-4 bg-slate-800 p-4 rounded">
              <div className="flex justify-between items-center mb-2">
                <h4 className="font-semibold">Quotation</h4>
                <div className="text-sm text-slate-400">Subtotal: {subtotal.toFixed(2)}</div>
              </div>
              <div className="space-y-2 max-h-48 overflow-auto">
                {items.map((it) => (
                  <div key={it.id} className="flex gap-2 items-center bg-slate-700 p-2 rounded">
                    <input value={it.name} onChange={(e) => updateItem(it.id, { name: e.target.value })} className="flex-1 p-1 rounded bg-slate-600" />
                    <input type="number" value={it.qty} onChange={(e) => updateItem(it.id, { qty: parseInt(e.target.value || 0) })} className="w-20 p-1 rounded bg-slate-600 text-right" />
                    <input type="number" value={it.price} onChange={(e) => updateItem(it.id, { price: parseFloat(e.target.value || 0) })} className="w-28 p-1 rounded bg-slate-600 text-right" />
                    <div className="w-24 text-right">{(it.qty * it.price).toFixed(2)}</div>
                    <button onClick={() => removeItem(it.id)} className="px-2 py-1 bg-red-600 rounded">X</button>
                  </div>
                ))}
              </div>
              <div className="flex gap-2 mt-3">
                <button onClick={addItem} className="px-3 py-1 bg-green-600 rounded">Add Item</button>
                <div className="ml-auto text-sm text-slate-300">
                  Tax ({Math.round(taxRate * 100)}%): {tax.toFixed(2)} • <span className="font-semibold">Total: {total.toFixed(2)}</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <footer className="mt-6 text-right">
          <button onClick={() => { setSelectedCustomer(null); setLogoUrl(null); }} className="px-3 py-2 mr-3 rounded bg-slate-700">Cancel</button>
          <button onClick={onSave} className="px-4 py-2 bg-blue-600 rounded">Save</button>
        </footer>
      </div>
    </div>
  );
}

To resolve the persistent issue where the **Transaction Modal** (Quotation/Production/Dispatch) and **Settings Modal** headers are getting cut off or not showing properly, I will apply a definitive fix.

**The Root Cause:** The application uses a page transition animation (`animate-fade-in-right`) which applies a CSS `transform`. This `transform` creates a new "stacking context," causing any `fixed` position elements (like Modals) inside it to be positioned relative to the *animation container* instead of the *viewport window*. This clips the modals.

**The Fix:** I will implement a **React Portal**. This forces the Modals to render directly into the `document.body`, completely bypassing the animation container and ensuring they are always 100% visible, draggable, and layered correctly on top of everything else.

I will also upgrade the `TransactionModal` to use the same robust, draggable, dark-header design as the Settings modal.

# Updated files:

## pages/ProfileSection.tsx

Refactored all modals to use `createPortal`, ensuring they break out of the animation container and display correctly. Upgraded `TransactionModal` UI to be draggable with a distinct header.

```tsx
import React, { useState, useMemo, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { useStore } from '../store/useStore';
import type { User, ToastMessage, Profile, ProfileTransaction, CompanySettings, Customer } from '../types';
import { SearchIcon, PencilIcon, TrashIcon, ChevronDownIcon, WarehouseIcon, CloudUploadIcon, UserPlusIcon, UserIcon } from '../components/Icon';

declare const XLSX: any;
declare const jspdf: any;

interface ProfileSectionProps {
    currentUser: User;
    addToast: (message: string, type: ToastMessage['type']) => void;
}

type Tab = 'Stock' | 'Production' | 'Dispatch' | 'Quotations' | 'Profiles' | 'Customers';

// --- PORTAL COMPONENT ---
// Forces modals to render in document.body, bypassing parent transforms/animations
const Portal: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    return createPortal(children, document.body);
};

const ProfileSection: React.FC<ProfileSectionProps> = ({ currentUser, addToast }) => {
    const store = useStore();
    const { 
        profiles, profileTransactions, brands, companySettings, customers,
        addProfile, updateProfile, deleteProfile, 
        addProfileTransaction, deleteProfileTransaction, updateProfileTransaction,
        addBrand, updateBrand, deleteBrand, resolveQuotation, updateCompanySettings,
        addCustomer, updateCustomer, deleteCustomer
    } = store;

    const [activeTab, setActiveTab] = useState<Tab>('Stock');
    const [searchTerm, setSearchTerm] = useState('');
    const [brandFilter, setBrandFilter] = useState<string>('All');
    const [isDownloadMenuOpen, setIsDownloadMenuOpen] = useState(false);
    const downloadMenuRef = useRef<HTMLDivElement>(null);

    // --- Filters ---
    const activeProfiles = useMemo(() => profiles.filter(p => !p.deletedAt), [profiles]);
    const activeTransactions = useMemo(() => profileTransactions.filter(t => !t.deletedAt), [profileTransactions]);
    const activeCustomers = useMemo(() => customers.filter(c => !c.deletedAt), [customers]);

    // --- State for Modals ---
    const [isAddProfileModalOpen, setIsAddProfileModalOpen] = useState(false);
    const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
    const [isManageBrandsModalOpen, setIsManageBrandsModalOpen] = useState(false);
    const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
    const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);

    const [transactionType, setTransactionType] = useState<'PRODUCTION' | 'DISPATCH' | 'QUOTATION'>('PRODUCTION');

    const [editingProfile, setEditingProfile] = useState<Profile | null>(null);
    const [editingTransaction, setEditingTransaction] = useState<ProfileTransaction | null>(null);
    const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);

    const tabs: { id: Tab; label: string }[] = [
        { id: 'Stock', label: 'Profile Stock' },
        { id: 'Production', label: 'Production (In)' },
        { id: 'Dispatch', label: 'Dispatch (Out)' },
        { id: 'Quotations', label: 'Quotations' },
        { id: 'Profiles', label: 'Profile List' },
        { id: 'Customers', label: 'Customers' },
    ];

    const canManage = currentUser.role !== 'VIEWER';

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (downloadMenuRef.current && !downloadMenuRef.current.contains(event.target as Node)) {
                setIsDownloadMenuOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [downloadMenuRef]);

    // Auto-reset filter if the selected brand is deleted
    useEffect(() => {
        if (brandFilter !== 'All' && !brands.includes(brandFilter)) {
            setBrandFilter('All');
        }
    }, [brands, brandFilter]);

    // --- Derived Data ---
    const brandFilteredProfiles = useMemo(() => {
        if (brandFilter === 'All') return activeProfiles;
        return activeProfiles.filter(p => p.brand === brandFilter);
    }, [activeProfiles, brandFilter]);

    const stockData = useMemo(() => {
        return brandFilteredProfiles.map(p => {
            const production = activeTransactions.filter(t => t.profileId === p.id && (t.type === 'PRODUCTION' || t.type === 'RETURN')).reduce((sum, t) => sum + t.quantity, 0);
            const dispatch = activeTransactions.filter(t => t.profileId === p.id && t.type === 'DISPATCH').reduce((sum, t) => sum + t.quantity, 0);
            const reserved = activeTransactions.filter(t => t.profileId === p.id && t.type === 'QUOTATION' && t.status !== 'CANCELLED').reduce((sum, t) => sum + t.quantity, 0);
            return { ...p, currentStock: production - dispatch - reserved, reservedStock: reserved };
        }).filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [brandFilteredProfiles, activeTransactions, searchTerm]);

    const productionData = useMemo(() => {
        const validProfileIds = new Set(brandFilteredProfiles.map(p => p.id));
        return activeTransactions.filter(t => (t.type === 'PRODUCTION' || t.type === 'RETURN') && validProfileIds.has(t.profileId)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [activeTransactions, brandFilteredProfiles]);

    const dispatchData = useMemo(() => {
        const validProfileIds = new Set(brandFilteredProfiles.map(p => p.id));
        const data = activeTransactions.filter(t => t.type === 'DISPATCH' && validProfileIds.has(t.profileId)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        if(searchTerm) return data.filter(t => t.refNo.toLowerCase().includes(searchTerm.toLowerCase()) || t.customer?.toLowerCase().includes(searchTerm.toLowerCase()));
        return data;
    }, [activeTransactions, brandFilteredProfiles, searchTerm]);

    const quotationData = useMemo(() => {
        const validProfileIds = new Set(brandFilteredProfiles.map(p => p.id));
        const data = activeTransactions.filter(t => t.type === 'QUOTATION' && validProfileIds.has(t.profileId)).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        if(searchTerm) return data.filter(t => t.refNo.toLowerCase().includes(searchTerm.toLowerCase()) || t.customer?.toLowerCase().includes(searchTerm.toLowerCase()));
        return data;
    }, [activeTransactions, brandFilteredProfiles, searchTerm]);

    const filteredProfiles = useMemo(() => brandFilteredProfiles.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase())), [brandFilteredProfiles, searchTerm]);
    const filteredCustomers = useMemo(() => activeCustomers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()) || c.phone?.includes(searchTerm) || c.gstin?.toLowerCase().includes(searchTerm.toLowerCase())), [activeCustomers, searchTerm]);

    const handleOpenTransactionModal = (type: 'PRODUCTION' | 'DISPATCH' | 'QUOTATION') => { setTransactionType(type); setIsTransactionModalOpen(true); };
    const handleQuotationAction = (id: string, action: 'CONFIRM' | 'CANCEL') => { resolveQuotation(id, action); if (action === 'CONFIRM') addToast('Confirmed!', 'success'); else addToast('Cancelled', 'info'); };
    const getProfileName = (id: string) => activeProfiles.find(p => p.id === id)?.name || 'Unknown';

    const getBrandBadge = (brand?: string) => {
        if (!brand) return <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300">-</span>;
        const colors = ['bg-blue-100 text-blue-800', 'bg-purple-100 text-purple-800', 'bg-green-100 text-green-800', 'bg-indigo-100 text-indigo-800', 'bg-pink-100 text-pink-800'];
        return <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${colors[brand.length % colors.length]}`}>{brand}</span>;
    };

    const generateDocumentPDF = (docType: 'QUOTATION' | 'INVOICE') => {
        const dataSet = docType === 'QUOTATION' ? quotationData : dispatchData;
        if (dataSet.length === 0) { addToast(`No ${docType.toLowerCase()}s to print.`, 'error'); return; }
        const firstRecord = dataSet[0];
        const { jsPDF } = jspdf;
        const doc = new jsPDF();
        const pageWidth = doc.internal.pageSize.getWidth();

        const brandColor = [41, 128, 185];
        doc.setFillColor(245, 245, 245); doc.rect(0, 0, pageWidth, 40, 'F'); 

        let logoWidth = 0;
        if (companySettings.logoUrl) {
            try { doc.addImage(companySettings.logoUrl, companySettings.logoUrl.startsWith('data:image/png') ? 'PNG' : 'JPEG', 15, 5, 35, 25); logoWidth = 35; } catch (e) {}
        }
        const textX = logoWidth > 0 ? 15 + logoWidth + 10 : 15;

        doc.setFontSize(18); doc.setTextColor(...brandColor); doc.setFont("helvetica", "bold"); doc.text(companySettings.name || "COMPANY NAME", textX, 15);
        doc.setFontSize(9); doc.setTextColor(60); doc.setFont("helvetica", "normal");
        let addrY = 21;
        if(companySettings.addressLine1) { doc.text(companySettings.addressLine1, textX, addrY); addrY += 4; }
        if(companySettings.addressLine2) { doc.text(companySettings.addressLine2, textX, addrY); addrY += 4; }
        doc.text(`${companySettings.cityStateZip} | GST: ${companySettings.gstin || "-"}`, textX, addrY);

        doc.setFontSize(24); doc.setTextColor(200); doc.setFont("helvetica", "bold");
        const title = docType === 'QUOTATION' ? "QUOTATION" : "TAX INVOICE";
        doc.text(title, pageWidth - 15 - doc.getTextWidth(title), 25);

        let yPos = 50;
        doc.setFontSize(10); doc.setTextColor(0); doc.setFont("helvetica", "bold"); doc.text("BILL TO:", 15, yPos);
        doc.setFont("helvetica", "normal"); doc.setFontSize(11); doc.text(firstRecord.customer || "Customer", 15, yPos + 6);
        let custY = yPos + 12; doc.setFontSize(10);
        if (firstRecord.customerAddress) { const split = doc.splitTextToSize(firstRecord.customerAddress, 80); doc.text(split, 15, custY); custY += (split.length * 4) + 2; }
        if (firstRecord.customerGST) { doc.text(`GSTIN: ${firstRecord.customerGST}`, 15, custY); custY += 5; }
        if (firstRecord.customerPhone) { doc.text(`Ph: ${firstRecord.customerPhone}`, 15, custY); custY += 5; }

        const col2X = pageWidth / 2 + 10;
        doc.setFont("helvetica", "bold"); doc.text(`${docType === 'QUOTATION' ? 'Quote' : 'Invoice'} #:`, col2X, yPos);
        doc.setFont("helvetica", "normal"); doc.text(firstRecord.refNo, col2X + 30, yPos);
        doc.setFont("helvetica", "bold"); doc.text("Date:", col2X, yPos + 6);
        doc.setFont("helvetica", "normal"); doc.text(new Date(firstRecord.date).toLocaleDateString(), col2X + 30, yPos + 6);

        yPos = Math.max(custY, yPos + 20) + 10;
        const tableData = dataSet.map((q, i) => {
            const p = activeProfiles.find(p => p.id === q.profileId);
            return [i + 1, p?.name, p?.sku, `${p?.length}m/${p?.weight}kg`, q.quantity, p?.price?.toLocaleString(), (q.quantity * (p?.price || 0)).toLocaleString()];
        });

        doc.autoTable({
            startY: yPos, head: [['#', 'Item', 'SKU', 'Specs', 'Qty', 'Rate', 'Amount']], body: tableData, theme: 'grid',
            headStyles: { fillColor: brandColor, textColor: 255, fontStyle: 'bold' }, styles: { fontSize: 9, cellPadding: 3 },
            columnStyles: { 0: { cellWidth: 10 }, 4: { halign: 'right' }, 5: { halign: 'right' }, 6: { halign: 'right', fontStyle: 'bold' } },
            foot: [['', '', '', '', '', 'Total', dataSet.reduce((s, q) => s + (q.quantity * (activeProfiles.find(p => p.id === q.profileId)?.price || 0)), 0).toLocaleString()]],
            footStyles: { fillColor: [245,245,245], textColor: 0, fontStyle: 'bold', halign: 'right' }
        });

        let finalY = (doc as any).lastAutoTable.finalY + 15;
        if (companySettings.bankName) {
             doc.setFontSize(9); doc.setFont("helvetica", "bold"); doc.text("Bank Details", 15, finalY);
             doc.setFont("helvetica", "normal"); finalY += 5;
             doc.text(`${companySettings.bankName} | A/c: ${companySettings.accountNo} | IFSC: ${companySettings.ifsc}`, 15, finalY); finalY += 8;
        }
        doc.setFont("helvetica", "bold"); doc.text("For " + companySettings.name, pageWidth - 15, finalY + 5, { align: 'right' });
        doc.save(`${docType}_${firstRecord.refNo}.pdf`);
    };

    const getActiveTableId = () => {
        switch (activeTab) {
            case 'Stock': return 'profile-stock-table';
            case 'Production': return 'profile-production-table';
            case 'Dispatch': return 'profile-dispatch-table';
            case 'Quotations': return 'profile-quotation-table';
            case 'Profiles': return 'profile-list-table';
            case 'Customers': return 'customer-list-table';
            default: return '';
        }
    };

    const handleExportExcel = () => {
        const tableId = getActiveTableId();
        const tableElement = document.getElementById(tableId)?.querySelector('table');
        if (!tableElement) return;
        const clonedTable = tableElement.cloneNode(true) as HTMLTableElement;
        const headers = Array.from(clonedTable.querySelectorAll('thead th'));
        const actionIndex = headers.findIndex(th => th.textContent?.includes('Action') || th.textContent?.includes('Edit'));
        if (actionIndex > -1) Array.from(clonedTable.rows).forEach(row => { if(row.cells[actionIndex]) row.deleteCell(actionIndex); });
        const wb = XLSX.utils.table_to_book(clonedTable, { sheet: "Sheet1" });
        XLSX.writeFile(wb, `Profile_${activeTab}.xlsx`);
    };

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Profile Stock</h1>
                 <div className="flex items-center gap-2 flex-wrap">
                     {canManage && <button onClick={() => setIsSettingsModalOpen(true)} className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-200 px-3 py-2 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 border border-gray-300 dark:border-gray-600 shadow-sm flex items-center gap-2"><WarehouseIcon className="w-4 h-4" /><span className="hidden sm:inline text-sm font-medium">Settings</span></button>}
                     <button onClick={handleExportExcel} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow">Download Excel</button>

                    <div className="flex bg-gray-200 dark:bg-gray-700 rounded-lg p-1 mr-2 items-center">
                        <button onClick={() => setBrandFilter('All')} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === 'All' ? 'bg-white dark:bg-gray-600 shadow text-gray-900 dark:text-white' : 'text-gray-500 dark:text-gray-400'}`}>All</button>
                        {brands.map(brand => <button key={brand} onClick={() => setBrandFilter(brand)} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === brand ? 'bg-white dark:bg-gray-600 shadow text-gray-900 dark:text-white' : 'text-gray-500 dark:text-gray-400'}`}>{brand}</button>)}
                        {canManage && <button onClick={() => setIsManageBrandsModalOpen(true)} className="ml-1 px-2 py-1 text-gray-500" title="Manage Brands"><PencilIcon className="w-3 h-3" /></button>}
                    </div>

                    {activeTab === 'Production' && canManage && <button onClick={() => handleOpenTransactionModal('PRODUCTION')} className="bg-green-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-green-700 shadow">+ Production</button>}
                    {activeTab === 'Dispatch' && canManage && <><button onClick={() => generateDocumentPDF('INVOICE')} className="bg-indigo-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-indigo-700 shadow">Print Invoice</button><button onClick={() => handleOpenTransactionModal('DISPATCH')} className="bg-red-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-red-700 shadow">- Dispatch</button></>}
                    {activeTab === 'Quotations' && canManage && <><button onClick={() => generateDocumentPDF('QUOTATION')} className="bg-indigo-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-indigo-700 shadow">Print Quote</button><button onClick={() => handleOpenTransactionModal('QUOTATION')} className="bg-orange-500 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-orange-600 shadow">+ Add Item</button></>}
                    {activeTab === 'Profiles' && canManage && <button onClick={() => setIsAddProfileModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow">+ Profile</button>}
                    {activeTab === 'Customers' && canManage && <button onClick={() => setIsCustomerModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow flex items-center gap-2"><UserPlusIcon className="w-4 h-4"/> Add Customer</button>}
                 </div>
            </div>

            <div className="mb-6 border-b border-gray-200 dark:border-gray-700 flex justify-between items-end">
                <nav className="-mb-px flex space-x-6 overflow-x-auto">
                    {tabs.map(tab => <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`${activeTab === tab.id ? 'border-blue-500 text-blue-600 dark:text-blue-400' : 'border-transparent text-gray-500 dark:text-gray-400'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm focus:outline-none`}>{tab.label}</button>)}
                </nav>
                 <div className="mb-2 relative hidden sm:block"><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="pl-8 pr-4 py-1 text-sm border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md w-64" /><SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" /></div>
            </div>

            <div>
                {activeTab === 'Stock' && (
                     <div id="profile-stock-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                        <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                            <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                                <tr>
                                    <th className="px-6 py-3">Brand</th><th className="px-6 py-3">SKU</th><th className="px-6 py-3">Profile Name</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Reserved</th><th className="px-6 py-3 text-right">Stock</th><th className="px-6 py-3 text-center">Status</th>{canManage && <th className="px-6 py-3 text-right">Edit</th>}
                                </tr>
                            </thead>
                            <tbody>
                                {stockData.map(p => (
                                    <tr key={p.id} className="bg-white dark:bg-gray-800 border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                                        <td className="px-6 py-4">{getBrandBadge(p.brand)}</td><td className="px-6 py-4 font-medium">{p.sku}</td><td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{p.name}</td><td className="px-6 py-4 text-xs text-gray-500">{p.length}m | {p.weight}kg</td><td className="px-6 py-4 text-right text-orange-500">{p.reservedStock > 0 ? `-${p.reservedStock}` : '-'}</td><td className="px-6 py-4 text-right"><span className="font-bold text-blue-600 text-lg">{p.currentStock}</span></td><td className="px-6 py-4 text-center">{p.currentStock < (p.reorderPoint || 0) ? <span className="text-red-500 font-bold">Low</span> : <span className="text-green-500">OK</span>}</td>
                                        {canManage && <td className="px-6 py-4 text-right"><button onClick={() => setEditingProfile(p)} className="text-blue-500 hover:underline">Edit</button></td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
                {(activeTab === 'Production' || activeTab === 'Dispatch') && (
                    <div id={`profile-${activeTab.toLowerCase()}-table`} className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                        <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                             <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                                <tr><th className="px-6 py-3">Date</th><th className="px-6 py-3">Ref No</th><th className="px-6 py-3">Profile</th><th className="px-6 py-3 text-right">Quantity</th>{activeTab === 'Dispatch' && <th className="px-6 py-3">Customer</th>}{canManage && <th className="px-6 py-3 text-right">Actions</th>}</tr>
                            </thead>
                            <tbody>
                                {(activeTab === 'Production' ? productionData : dispatchData).map(t => (
                                    <tr key={t.id} className="bg-white dark:bg-gray-800 border-b dark:border-gray-700">
                                        <td className="px-6 py-4">{new Date(t.date).toLocaleDateString()}</td><td className="px-6 py-4 font-medium">{t.refNo}</td><td className="px-6 py-4">{getProfileName(t.profileId)}</td><td className={`px-6 py-4 text-right font-semibold ${activeTab === 'Production' ? 'text-green-600' : 'text-red-600'}`}>{t.quantity}</td>{activeTab === 'Dispatch' && <td className="px-6 py-4">{t.customer}</td>}{canManage && <td className="px-6 py-4 text-right space-x-3"><button onClick={() => setEditingTransaction(t)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => deleteProfileTransaction(t.id)} className="text-red-500 hover:underline">Delete</button></td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
                {activeTab === 'Quotations' && (
                    <div id="profile-quotation-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                        <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                            <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                                <tr><th className="px-6 py-3">Date</th><th className="px-6 py-3">Ref No</th><th className="px-6 py-3">Customer</th><th className="px-6 py-3">Profile</th><th className="px-6 py-3 text-right">Qty</th><th className="px-6 py-3 text-center">Status</th>{canManage && <th className="px-6 py-3 text-center">Confirm</th>}{canManage && <th className="px-6 py-3 text-right">Actions</th>}</tr>
                            </thead>
                            <tbody>
                                {quotationData.map(t => (
                                    <tr key={t.id} className={`bg-white dark:bg-gray-800 border-b dark:border-gray-700 ${t.status === 'CANCELLED' ? 'opacity-50' : ''}`}>
                                        <td className="px-6 py-4">{new Date(t.date).toLocaleDateString()}</td><td className="px-6 py-4 font-medium">{t.refNo}</td><td className="px-6 py-4">{t.customer}</td><td className="px-6 py-4">{getProfileName(t.profileId)}</td><td className="px-6 py-4 text-right text-orange-600 font-semibold">{t.quantity}</td>
                                        <td className="px-6 py-4 text-center"><span className={`px-2 py-1 rounded-full text-xs ${t.status === 'PENDING' ? 'bg-yellow-100 text-yellow-800' : t.status === 'COMPLETED' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>{t.status}</span></td>
                                        {canManage && <td className="px-6 py-4 text-center space-x-2">{t.status === 'PENDING' && <><button onClick={() => handleQuotationAction(t.id, 'CONFIRM')} className="text-green-600 hover:text-green-800 font-bold">✓</button><button onClick={() => handleQuotationAction(t.id, 'CANCEL')} className="text-red-500 hover:text-red-700 font-bold">✕</button></>}</td>}
                                        {canManage && <td className="px-6 py-4 text-right space-x-2"><button onClick={() => setEditingTransaction(t)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => deleteProfileTransaction(t.id)} className="text-red-500 hover:underline">Del</button></td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
                {activeTab === 'Profiles' && (
                     <div id="profile-list-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                        <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                            <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700"><tr><th className="px-6 py-3">Brand</th><th className="px-6 py-3">SKU</th><th className="px-6 py-3">Name</th><th className="px-6 py-3">Price</th>{canManage && <th className="px-6 py-3 text-right">Actions</th>}</tr></thead>
                            <tbody>
                                {filteredProfiles.map(p => (
                                    <tr key={p.id} className="bg-white dark:bg-gray-800 border-b dark:border-gray-700">
                                        <td className="px-6 py-4">{getBrandBadge(p.brand)}</td><td className="px-6 py-4">{p.sku}</td><td className="px-6 py-4">{p.name}</td><td className="px-6 py-4">{p.price?.toLocaleString()}</td>
                                        {canManage && <td className="px-6 py-4 text-right space-x-3"><button onClick={() => setEditingProfile(p)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => deleteProfile(p.id)} className="text-red-500 hover:underline">Delete</button></td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
                {activeTab === 'Customers' && (
                    <div id="customer-list-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                        <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                            <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700"><tr><th className="px-6 py-3">Customer Name</th><th className="px-6 py-3">Phone</th><th className="px-6 py-3">GSTIN</th><th className="px-6 py-3">Address</th>{canManage && <th className="px-6 py-3 text-right">Actions</th>}</tr></thead>
                            <tbody>
                                {filteredCustomers.map(c => (
                                    <tr key={c.id} className="bg-white dark:bg-gray-800 border-b dark:border-gray-700">
                                        <td className="px-6 py-4 font-medium text-gray-900 dark:text-white flex items-center gap-2"><UserIcon className="w-4 h-4 text-gray-400"/> {c.name}</td><td className="px-6 py-4">{c.phone || '-'}</td><td className="px-6 py-4">{c.gstin || '-'}</td><td className="px-6 py-4 text-xs max-w-xs truncate">{c.address || '-'}</td>
                                        {canManage && <td className="px-6 py-4 text-right space-x-3"><button onClick={() => setEditingCustomer(c)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => deleteCustomer(c.id)} className="text-red-500 hover:underline">Delete</button></td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* MODALS - WRAPPED IN PORTAL FOR ROBUST LAYOUT */}
            <ManageBrandsModal isOpen={isManageBrandsModalOpen} onClose={() => setIsManageBrandsModalOpen(false)} brands={brands} addBrand={addBrand} updateBrand={updateBrand} deleteBrand={deleteBrand} addToast={addToast} />
            <CompanySettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={companySettings} updateSettings={updateCompanySettings} addToast={addToast} />
            <AddProfileModal isOpen={isAddProfileModalOpen} onClose={() => setIsAddProfileModalOpen(false)} onAdd={addProfile} brands={brands} addToast={addToast} />
            {editingProfile && <EditProfileModal isOpen={!!editingProfile} onClose={() => setEditingProfile(null)} profile={editingProfile} onUpdate={updateProfile} brands={brands} addToast={addToast} />}
            <TransactionModal isOpen={isTransactionModalOpen} onClose={() => setIsTransactionModalOpen(false)} type={transactionType} profiles={activeProfiles} onAdd={addProfileTransaction} addToast={addToast} customers={customers} addCustomer={addCustomer}/>
            {editingTransaction && <EditTransactionModal isOpen={!!editingTransaction} onClose={() => setEditingTransaction(null)} transaction={editingTransaction} profiles={activeProfiles} onUpdate={updateProfileTransaction} addToast={addToast} />}
            <CustomerModal isOpen={isCustomerModalOpen || !!editingCustomer} onClose={() => { setIsCustomerModalOpen(false); setEditingCustomer(null); }} customer={editingCustomer} onSave={(c) => { if (editingCustomer) updateCustomer({ ...editingCustomer, ...c }); else addCustomer(c); }} addToast={addToast} />
        </div>
    );
};

// --- CUSTOMER MODAL ---
const CustomerModal: React.FC<{ isOpen: boolean; onClose: () => void; customer: Customer | null; onSave: (c: any) => void; addToast: any }> = ({ isOpen, onClose, customer, onSave, addToast }) => {
    const [form, setForm] = useState({ name: '', phone: '', gstin: '', address: '' });
    useEffect(() => { if (isOpen) setForm({ name: customer?.name || '', phone: customer?.phone || '', gstin: customer?.gstin || '', address: customer?.address || '' }); }, [isOpen, customer]);
    if (!isOpen) return null;
    const handleSubmit = (e: React.FormEvent) => { e.preventDefault(); if (!form.name) { addToast('Customer name is required', 'error'); return; } onSave(form); onClose(); };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none focus:ring-1 focus:ring-blue-500";
    return (
        <Portal>
            <div className="fixed inset-0 bg-black bg-opacity-60 z-[80] flex justify-center items-center p-4" onClick={onClose}>
                <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
                    <h2 className="text-xl font-bold mb-4 dark:text-white">{customer ? 'Edit Customer' : 'Add New Customer'}</h2>
                    <form onSubmit={handleSubmit} className="space-y-3">
                        <div><label className="block text-xs font-medium dark:text-gray-300">Name</label><input value={form.name} onChange={e => setForm({...form, name: e.target.value})} className={inputClass} required /></div>
                        <div className="grid grid-cols-2 gap-3"><div><label className="block text-xs font-medium dark:text-gray-300">Phone</label><input value={form.phone} onChange={e => setForm({...form, phone: e.target.value})} className={inputClass} /></div><div><label className="block text-xs font-medium dark:text-gray-300">GSTIN</label><input value={form.gstin} onChange={e => setForm({...form, gstin: e.target.value})} className={inputClass} /></div></div>
                        <div><label className="block text-xs font-medium dark:text-gray-300">Address</label><textarea value={form.address} onChange={e => setForm({...form, address: e.target.value})} className={inputClass} rows={3} /></div>
                        <div className="flex justify-end gap-2 pt-4"><button type="button" onClick={onClose} className="px-4 py-2 border rounded text-gray-600 dark:text-gray-300">Cancel</button><button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded shadow">Save</button></div>
                    </form>
                </div>
            </div>
        </Portal>
    );
};

// --- SETTINGS MODAL (Draggable & Robust) ---
const CompanySettingsModal: React.FC<{ isOpen: boolean; onClose: () => void; settings: CompanySettings; updateSettings: any; addToast: any; }> = ({ isOpen, onClose, settings, updateSettings, addToast }) => {
    const [form, setForm] = useState(settings);
    const [logoPreview, setLogoPreview] = useState(settings.logoUrl || '');
    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    useEffect(() => { if(isOpen) { setForm(settings); setLogoPreview(settings.logoUrl || ''); setPosition({ x: 0, y: 0 }); } }, [isOpen, settings]);
    const onMouseDownHeader = (e: React.MouseEvent) => { if (e.button !== 0) return; setIsDragging(true); dragStart.current = { x: e.clientX, y: e.clientY }; startPos.current = { ...position }; };
    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => { if (isDragging) { e.preventDefault(); setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) }); } };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) { document.addEventListener('mousemove', onMouseMove); document.addEventListener('mouseup', onMouseUp); }
        return () => { document.removeEventListener('mousemove', onMouseMove); document.removeEventListener('mouseup', onMouseUp); };
    }, [isDragging]);

    if(!isOpen) return null;
    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (file) { const reader = new FileReader(); reader.onloadend = () => { const result = reader.result as string; setForm({ ...form, logoUrl: result }); setLogoPreview(result); }; reader.readAsDataURL(file); } };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white p-2 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none";
    const labelClass = "block text-xs font-medium mb-1 text-gray-700 dark:text-gray-300";

    return (
        <Portal>
            <div className="fixed inset-0 bg-black bg-opacity-60 z-[100] flex justify-center items-center p-4" onMouseDown={onClose}>
                <div ref={modalRef} style={{ transform: `translate(${position.x}px, ${position.y}px)` }} className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-4xl flex flex-col max-h-[90vh] border border-gray-200 dark:border-gray-600 my-auto" onMouseDown={e => e.stopPropagation()}>
                    <div onMouseDown={onMouseDownHeader} className="bg-gray-900 text-white px-6 py-4 rounded-t-xl cursor-move flex justify-between items-center shrink-0 select-none z-10 relative min-h-[64px]"><h2 className="text-xl font-bold flex items-center gap-2"><WarehouseIcon className="w-6 h-6 text-blue-400"/> Company Settings</h2><button onClick={onClose} className="text-gray-400 hover:text-white text-2xl font-bold">&times;</button></div>
                    <div className="p-6 overflow-y-auto flex-1 min-h-0 bg-white dark:bg-gray-800">
                        <div className="flex flex-col items-center p-6 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-700 mb-6">
                            <div className="w-48 h-32 bg-white dark:bg-black/20 border border-gray-300 dark:border-gray-600 rounded-lg flex items-center justify-center overflow-hidden mb-4 shadow-sm">{logoPreview ? <img src={logoPreview} alt="Logo" className="max-w-full max-h-full object-contain" /> : <span className="text-gray-400 text-xs">No Logo</span>}</div>
                            <label className="cursor-pointer bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-bold hover:bg-blue-700 flex gap-2"><CloudUploadIcon className="w-4 h-4"/> Upload Logo <input type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" /></label>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
