                        <div className="flex justify-end gap-2 pt-4"><button type="button" onClick={onClose} className="px-4 py-2 border rounded text-gray-600 dark:text-gray-300">Cancel</button><button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded shadow">Save</button></div>
                    </form>
                </div>
            </div>
        </Portal>
    );
};

// --- SETTINGS MODAL (Draggable & Robust) ---
const CompanySettingsModal: React.FC<{ isOpen: boolean; onClose: () => void; settings: CompanySettings; updateSettings: any; addToast: any; }> = ({ isOpen, onClose, settings, updateSettings, addToast }) => {
    const [form, setForm] = useState(settings);
    const [logoPreview, setLogoPreview] = useState(settings.logoUrl || '');
    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    useEffect(() => { if(isOpen) { setForm(settings); setLogoPreview(settings.logoUrl || ''); setPosition({ x: 0, y: 0 }); } }, [isOpen, settings]);
    const onMouseDownHeader = (e: React.MouseEvent) => { if (e.button !== 0) return; setIsDragging(true); dragStart.current = { x: e.clientX, y: e.clientY }; startPos.current = { ...position }; };
    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => { if (isDragging) { e.preventDefault(); setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) }); } };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) { document.addEventListener('mousemove', onMouseMove); document.addEventListener('mouseup', onMouseUp); }
        return () => { document.removeEventListener('mousemove', onMouseMove); document.removeEventListener('mouseup', onMouseUp); };
    }, [isDragging]);

    if(!isOpen) return null;
    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (file) { const reader = new FileReader(); reader.onloadend = () => { const result = reader.result as string; setForm({ ...form, logoUrl: result }); setLogoPreview(result); }; reader.readAsDataURL(file); } };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white p-2 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none";
    const labelClass = "block text-xs font-medium mb-1 text-gray-700 dark:text-gray-300";

    return (
        <Portal>
            <div className="fixed inset-0 bg-black bg-opacity-60 z-[100] flex justify-center items-center p-4" onMouseDown={onClose}>
                <div ref={modalRef} style={{ transform: `translate(${position.x}px, ${position.y}px)` }} className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-4xl flex flex-col max-h-[90vh] border border-gray-200 dark:border-gray-600 my-auto" onMouseDown={e => e.stopPropagation()}>
                    <div onMouseDown={onMouseDownHeader} className="bg-gray-900 text-white px-6 py-4 rounded-t-xl cursor-move flex justify-between items-center shrink-0 select-none z-10 relative min-h-[64px]"><h2 className="text-xl font-bold flex items-center gap-2"><WarehouseIcon className="w-6 h-6 text-blue-400"/> Company Settings</h2><button onClick={onClose} className="text-gray-400 hover:text-white text-2xl font-bold">&times;</button></div>
                    <div className="p-6 overflow-y-auto flex-1 min-h-0 bg-white dark:bg-gray-800">
                        <div className="flex flex-col items-center p-6 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-700 mb-6">
                            <div className="w-48 h-32 bg-white dark:bg-black/20 border border-gray-300 dark:border-gray-600 rounded-lg flex items-center justify-center overflow-hidden mb-4 shadow-sm">{logoPreview ? <img src={logoPreview} alt="Logo" className="max-w-full max-h-full object-contain" /> : <span className="text-gray-400 text-xs">No Logo</span>}</div>
                            <label className="cursor-pointer bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-bold hover:bg-blue-700 flex gap-2"><CloudUploadIcon className="w-4 h-4"/> Upload Logo <input type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" /></label>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-4"><h3 className="font-bold border-b pb-2 text-gray-800 dark:text-gray-200">General Info</h3><div><label className={labelClass}>Company Name</label><input value={form.name} onChange={e => setForm({...form, name: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>GSTIN</label><input value={form.gstin} onChange={e => setForm({...form, gstin: e.target.value})} className={inputClass} /></div><div className="grid grid-cols-2 gap-3"><div><label className={labelClass}>Phone</label><input value={form.phone} onChange={e => setForm({...form, phone: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Email</label><input value={form.email} onChange={e => setForm({...form, email: e.target.value})} className={inputClass} /></div></div></div>
                            <div className="space-y-4"><h3 className="font-bold border-b pb-2 text-gray-800 dark:text-gray-200">Address</h3><div><label className={labelClass}>Address Line 1</label><input value={form.addressLine1} onChange={e => setForm({...form, addressLine1: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Address Line 2</label><input value={form.addressLine2} onChange={e => setForm({...form, addressLine2: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>City, State, Zip</label><input value={form.cityStateZip} onChange={e => setForm({...form, cityStateZip: e.target.value})} className={inputClass} /></div></div>
                        </div>
                        <div className="mt-6 space-y-4"><h3 className="font-bold border-b pb-2 text-gray-800 dark:text-gray-200">Bank & Terms</h3><div className="grid grid-cols-2 gap-4"><div><label className={labelClass}>Bank Name</label><input value={form.bankName} onChange={e => setForm({...form, bankName: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Account No</label><input value={form.accountNo} onChange={e => setForm({...form, accountNo: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>IFSC</label><input value={form.ifsc} onChange={e => setForm({...form, ifsc: e.target.value})} className={inputClass} /></div><div><label className={labelClass}>Branch</label><input value={form.branch} onChange={e => setForm({...form, branch: e.target.value})} className={inputClass} /></div></div><div><label className={labelClass}>Terms</label><textarea value={form.terms} onChange={e => setForm({...form, terms: e.target.value})} className={inputClass} rows={2} /></div></div>
                    </div>
                    <div className="p-4 bg-gray-100 dark:bg-gray-700 rounded-b-xl flex justify-end gap-3 shrink-0 border-t border-gray-200 dark:border-gray-600"><button onClick={onClose} className="px-5 py-2 bg-white dark:bg-gray-600 border rounded-md hover:bg-gray-50 dark:hover:bg-gray-500 text-gray-700 dark:text-white transition-colors">Cancel</button><button onClick={() => { updateSettings(form); addToast('Settings Saved', 'success'); onClose(); }} className="px-6 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 shadow transition-colors">Save Settings</button></div>
                </div>
            </div>
        </Portal>
    )
};

// --- TRANSACTION MODAL (Fixed & Robust) ---
const TransactionModal: React.FC<{ isOpen: boolean; onClose: () => void; type: any; profiles: any; onAdd: any; addToast: any; customers: Customer[]; addCustomer: any }> = ({ isOpen, onClose, type, profiles, onAdd, addToast, customers, addCustomer }) => {
    const [form, setForm] = useState({ profileId: profiles[0]?.id || '', quantity: '', refNo: '', date: new Date().toISOString().split('T')[0], customer: '', customerAddress: '', customerGST: '', customerPhone: '', machine: '', die: '' });
    const [customerSearch, setCustomerSearch] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);

    // Drag state
    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    useEffect(() => { if(isOpen) { setForm(prev => ({...prev, profileId: profiles[0]?.id || '', quantity: '', refNo: '', machine: '', die: ''})); setPosition({ x: 0, y: 0 }); } }, [isOpen, profiles]);

    const onMouseDownHeader = (e: React.MouseEvent) => { if (e.button !== 0) return; setIsDragging(true); dragStart.current = { x: e.clientX, y: e.clientY }; startPos.current = { ...position }; };
    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => { if (isDragging) { e.preventDefault(); setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) }); } };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) { document.addEventListener('mousemove', onMouseMove); document.addEventListener('mouseup', onMouseUp); }
        return () => { document.removeEventListener('mousemove', onMouseMove); document.removeEventListener('mouseup', onMouseUp); };
    }, [isDragging]);

    if(!isOpen) return null;

    const filteredCustomers = customers.filter(c => c.name.toLowerCase().includes(customerSearch.toLowerCase()) && !c.deletedAt);
    const selectCustomer = (c: Customer) => { setForm(prev => ({ ...prev, customer: c.name, customerAddress: c.address || '', customerGST: c.gstin || '', customerPhone: c.phone || '' })); setCustomerSearch(c.name); setShowSuggestions(false); };
    const handleSaveCustomer = () => { if (!form.customer) return; addCustomer({ name: form.customer, address: form.customerAddress, gstin: form.customerGST, phone: form.customerPhone }); addToast('Customer saved', 'success'); };
    const handleSubmit = (e: React.FormEvent) => { e.preventDefault(); onAdd({ ...form, quantity: parseFloat(form.quantity), type }); onClose(); };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none focus:ring-1 focus:ring-blue-500";

    return (
        <Portal>
            <div className="fixed inset-0 bg-black bg-opacity-60 z-[90] flex justify-center items-center p-4" onMouseDown={onClose}>
                <div ref={modalRef} style={{ transform: `translate(${position.x}px, ${position.y}px)` }} className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md flex flex-col max-h-[90vh] my-auto" onMouseDown={e => e.stopPropagation()}>
                    <div onMouseDown={onMouseDownHeader} className="px-6 py-4 bg-gray-900 text-white rounded-t-xl border-b border-gray-700 flex justify-between items-center shrink-0 cursor-move select-none relative z-10 min-h-[60px]">
                        <h2 className="text-xl font-bold">{type === 'QUOTATION' ? 'Create Quotation' : type === 'DISPATCH' ? 'Record Dispatch' : type === 'SCRAP' ? 'Record Scrap' : 'Record Production'}</h2>
                        <button onClick={onClose} className="text-gray-400 hover:text-white text-2xl leading-none">&times;</button>
                    </div>
                    <div className="p-6 overflow-y-auto flex-1 min-h-0">
                        <form onSubmit={handleSubmit} className="space-y-3">
                            <div><label className="block text-xs font-medium dark:text-gray-300">Date</label><input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} className={inputClass} required /></div>
                            <div><label className="block text-xs font-medium dark:text-gray-300">Profile</label><select value={form.profileId} onChange={e => setForm({...form, profileId: e.target.value})} className={inputClass}>{profiles.map((p:any) => <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}</select></div>
                            <div><label className="block text-xs font-medium dark:text-gray-300">Ref No.</label><input value={form.refNo} onChange={e => setForm({...form, refNo: e.target.value})} className={inputClass} required /></div>
                            <div><label className="block text-xs font-medium dark:text-gray-300">Quantity</label><input type="number" value={form.quantity} onChange={e => setForm({...form, quantity: e.target.value})} className={inputClass} required /></div>

                            {type === 'SCRAP' && (
                                <div className="grid grid-cols-2 gap-2">
                                    <div><label className="block text-xs font-medium dark:text-gray-300">Machine No.</label><input value={form.machine} onChange={e => setForm({...form, machine: e.target.value})} className={inputClass} /></div>
                                    <div><label className="block text-xs font-medium dark:text-gray-300">Die No.</label><input value={form.die} onChange={e => setForm({...form, die: e.target.value})} className={inputClass} /></div>
                                </div>
                            )}

                            {(type === 'QUOTATION' || type === 'DISPATCH') && (
                                <>
                                    <div className="relative">
                                        <label className="block text-xs font-medium dark:text-gray-300">Customer Name (Search)</label>
                                        <input value={form.customer} onChange={e => { setForm({...form, customer: e.target.value}); setCustomerSearch(e.target.value); setShowSuggestions(true); }} onFocus={() => setShowSuggestions(true)} className={inputClass} required placeholder="Type to search..." />
                                        {showSuggestions && customerSearch && filteredCustomers.length > 0 && (
                                            <div className="absolute z-20 w-full bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-md shadow-lg max-h-40 overflow-y-auto mt-1">
                                                {filteredCustomers.map(c => (
                                                    <div key={c.id} onClick={() => selectCustomer(c)} className="px-3 py-2 hover:bg-gray-100 dark:hover:bg-gray-600 cursor-pointer text-sm"><div className="font-medium">{c.name}</div><div className="text-xs text-gray-500">{c.phone}</div></div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                    <div className="bg-gray-50 dark:bg-gray-900/50 p-3 rounded border dark:border-gray-700 space-y-2">
                                        <div className="flex justify-between items-center"><p className="text-xs font-bold text-gray-500">Customer Details</p><button type="button" onClick={handleSaveCustomer} className="text-xs text-blue-600 hover:underline flex items-center gap-1"><UserPlusIcon className="w-3 h-3"/> Save Customer</button></div>
                                        <input placeholder="Address" value={form.customerAddress} onChange={e => setForm({...form, customerAddress: e.target.value})} className={inputClass}/>
                                        <div className="grid grid-cols-2 gap-2"><input placeholder="GSTIN" value={form.customerGST} onChange={e => setForm({...form, customerGST: e.target.value})} className={inputClass}/><input placeholder="Mobile" value={form.customerPhone} onChange={e => setForm({...form, customerPhone: e.target.value})} className={inputClass}/></div>
                                    </div>
                                </>
                            )}
                            <div className="flex justify-end gap-2 pt-4"><button type="button" onClick={onClose} className="px-4 py-2 border rounded text-gray-600 dark:text-gray-300">Cancel</button><button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded shadow">Save</button></div>
                        </form>
                    </div>
                </div>
            </div>
        </Portal>
    );
};

const EditTransactionModal: React.FC<{ isOpen: boolean; onClose: () => void; transaction: any; profiles: any; onUpdate: any; addToast: any; }> = ({ isOpen, onClose, transaction, profiles, onUpdate, addToast }) => {
