        if (firstRecord.customerPhone) { doc.text(`Ph: ${firstRecord.customerPhone}`, 15, custY); custY += 5; }

        const col2X = pageWidth / 2 + 10;
        doc.setFont("helvetica", "bold"); doc.text(`${docType === 'QUOTATION' ? 'Quote' : 'Invoice'} #:`, col2X, yPos);
        doc.setFont("helvetica", "normal"); doc.text(firstRecord.refNo, col2X + 30, yPos);
        doc.setFont("helvetica", "bold"); doc.text("Date:", col2X, yPos + 6);
        doc.setFont("helvetica", "normal"); doc.text(new Date(firstRecord.date).toLocaleDateString(), col2X + 30, yPos + 6);

        yPos = Math.max(custY, yPos + 20) + 10;
        const tableData = dataSet.map((q, i) => {
            const p = activeProfiles.find(p => p.id === q.profileId);
            return [i + 1, p?.name, p?.sku, `${p?.length}m/${p?.weight}kg`, q.quantity, p?.price?.toLocaleString(), (q.quantity * (p?.price || 0)).toLocaleString()];
        });

        doc.autoTable({
            startY: yPos, head: [['#', 'Item', 'SKU', 'Specs', 'Qty', 'Rate', 'Amount']], body: tableData, theme: 'grid',
            headStyles: { fillColor: brandColor, textColor: 255, fontStyle: 'bold' }, styles: { fontSize: 9, cellPadding: 3 },
            columnStyles: { 0: { cellWidth: 10 }, 4: { halign: 'right' }, 5: { halign: 'right' }, 6: { halign: 'right', fontStyle: 'bold' } },
            foot: [['', '', '', '', '', 'Total', dataSet.reduce((s, q) => s + (q.quantity * (activeProfiles.find(p => p.id === q.profileId)?.price || 0)), 0).toLocaleString()]],
            footStyles: { fillColor: [245,245,245], textColor: 0, fontStyle: 'bold', halign: 'right' }
        });

        let finalY = (doc as any).lastAutoTable.finalY + 15;
        if (companySettings.bankName) {
             doc.setFontSize(9); doc.setFont("helvetica", "bold"); doc.text("Bank Details", 15, finalY);
             doc.setFont("helvetica", "normal"); finalY += 5;
             doc.text(`${companySettings.bankName} | A/c: ${companySettings.accountNo} | IFSC: ${companySettings.ifsc}`, 15, finalY); finalY += 8;
        }
        doc.setFont("helvetica", "bold"); doc.text("For " + companySettings.name, pageWidth - 15, finalY + 5, { align: 'right' });
        doc.save(`${docType}_${firstRecord.refNo}.pdf`);
    };

    const getActiveTableId = () => {
        switch (activeTab) {
            case 'Stock': return 'profile-stock-table';
            case 'Planning': return 'profile-planning-table';
            case 'Production': return 'profile-production-table';
            case 'Dispatch': return 'profile-dispatch-table';
            case 'Scrap': return 'profile-scrap-table';
            case 'Quotations': return 'profile-quotation-table';
            case 'Profiles': return 'profile-list-table';
            case 'Customers': return 'customer-list-table';
            default: return '';
        }
    };

    const handleExportPdf = () => {
        const tableId = getActiveTableId();
        const tableContainer = document.getElementById(tableId);
        if (!tableContainer) {
            addToast('No table found to export', 'error');
            return;
        }
        const tableElement = tableContainer.querySelector('table');
        if (!tableElement) return;

        const { jsPDF } = jspdf;
        const doc = new jsPDF({ orientation: 'landscape' });

        const reportTitle = tabs.find(t => t.id === activeTab)?.label || 'Profile Report';
        const date = new Date().toLocaleDateString();
        doc.text(`${reportTitle} - Generated on: ${date}`, 14, 15);

        const clonedTable = tableElement.cloneNode(true) as HTMLTableElement;
        const headers = Array.from(clonedTable.querySelectorAll('thead th'));
        const columnsToRemove = headers.reduce((acc, th, index) => {
             const text = th.textContent?.toLowerCase() || '';
             if (text.includes('action') || text.includes('edit') || text.includes('confirm')) {
                 acc.push(index);
             }
             return acc;
        }, [] as number[]);

        columnsToRemove.sort((a, b) => b - a).forEach(index => {
            Array.from(clonedTable.rows).forEach(row => {
                if (row.cells[index]) row.deleteCell(index);
            });
        });

        doc.autoTable({
            html: clonedTable,
            startY: 20,
            theme: 'grid',
            styles: { fontSize: 8 },
            headStyles: { fillColor: [55, 74, 103] },
        });

        doc.save(`${reportTitle.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.pdf`);
        setIsDownloadMenuOpen(false);
    };

    const handleExportExcel = () => {
        const tableId = getActiveTableId();
        const tableElement = document.getElementById(tableId)?.querySelector('table');
        if (!tableElement) return;
        const clonedTable = tableElement.cloneNode(true) as HTMLTableElement;
        const headers = Array.from(clonedTable.querySelectorAll('thead th'));
        const columnsToRemove = headers.reduce((acc, th, index) => {
             const text = th.textContent?.toLowerCase() || '';
             if (text.includes('action') || text.includes('edit') || text.includes('confirm')) {
                 acc.push(index);
             }
             return acc;
        }, [] as number[]);

        columnsToRemove.sort((a, b) => b - a).forEach(index => {
            Array.from(clonedTable.rows).forEach(row => {
                 if(row.cells[index]) row.deleteCell(index);
            });
        });
        const wb = XLSX.utils.table_to_book(clonedTable, { sheet: "Sheet1" });
        XLSX.writeFile(wb, `Profile_${activeTab}.xlsx`);
        setIsDownloadMenuOpen(false);
    };

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Profile Stock</h1>
                 <div className="flex items-center gap-2 flex-wrap">
                     {canManage && <button onClick={() => setIsSettingsModalOpen(true)} className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-200 px-3 py-2 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 border border-gray-300 dark:border-gray-600 shadow-sm flex items-center gap-2"><WarehouseIcon className="w-4 h-4" /><span className="hidden sm:inline text-sm font-medium">Settings</span></button>}

                    <div className="relative" ref={downloadMenuRef}>
                        <button
                            onClick={() => setIsDownloadMenuOpen(prev => !prev)}
                            className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow flex items-center gap-2"
                        >
                            Download
                            <ChevronDownIcon className={`w-4 h-4 transition-transform ${isDownloadMenuOpen ? 'rotate-180' : ''}`} />
                        </button>
                        {isDownloadMenuOpen && (
                            <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-gray-800 rounded-md shadow-lg py-1 z-20 ring-1 ring-black ring-opacity-5 border dark:border-gray-700">
                                <button onClick={handleExportPdf} className="block w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700">
                                    Download as PDF
                                </button>
                                <button onClick={handleExportExcel} className="block w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700">
                                    Download as Excel
                                </button>
                            </div>
                        )}
                    </div>

                    <div className="flex bg-gray-200 dark:bg-gray-700 rounded-lg p-1 mr-2 items-center">
                         {activeTab === 'Planning' && (
                            <select 
                                value={planningTimeFilter}
                                onChange={(e) => setPlanningTimeFilter(e.target.value as any)}
                                className="mr-2 bg-white dark:bg-gray-600 border-none rounded-md text-xs font-medium px-2 py-1.5 focus:ring-0 cursor-pointer"
                            >
                                <option value="1M">Last 1 Month</option>
                                <option value="3M">Last 3 Months</option>
                                <option value="6M">Last 6 Months</option>
                                <option value="ALL">All Time</option>
                            </select>
                        )}
                        <button onClick={() => setBrandFilter('All')} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === 'All' ? 'bg-white dark:bg-gray-600 shadow text-gray-900 dark:text-white' : 'text-gray-500 dark:text-gray-400'}`}>All</button>
                        {brands.map(brand => <button key={brand} onClick={() => setBrandFilter(brand)} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === brand ? 'bg-white dark:bg-gray-600 shadow text-gray-900 dark:text-white' : 'text-gray-500 dark:text-gray-400'}`}>{brand}</button>)}
                        {canManage && <button onClick={() => setIsManageBrandsModalOpen(true)} className="ml-1 px-2 py-1 text-gray-500" title="Manage Brands"><PencilIcon className="w-3 h-3" /></button>}
                    </div>

                    {activeTab === 'Production' && canManage && <button onClick={() => handleOpenTransactionModal('PRODUCTION')} className="bg-green-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-green-700 shadow">+ Production</button>}
                    {activeTab === 'Dispatch' && canManage && <><button onClick={() => generateDocumentPDF('INVOICE')} className="bg-indigo-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-indigo-700 shadow">Print Invoice</button><button onClick={() => handleOpenTransactionModal('DISPATCH')} className="bg-red-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-red-700 shadow">- Dispatch</button></>}
                    {activeTab === 'Scrap' && canManage && <button onClick={() => handleOpenTransactionModal('SCRAP')} className="bg-red-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-red-700 shadow flex items-center gap-1"><TrashIcon className="w-4 h-4"/> Record Scrap</button>}
                    {activeTab === 'Quotations' && canManage && <><button onClick={() => generateDocumentPDF('QUOTATION')} className="bg-indigo-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-indigo-700 shadow">Print Quote</button><button onClick={() => handleOpenTransactionModal('QUOTATION')} className="bg-orange-500 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-orange-600 shadow">+ Add Item</button></>}
                    {activeTab === 'Profiles' && canManage && <button onClick={() => setIsAddProfileModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow">+ Profile</button>}
                    {activeTab === 'Customers' && canManage && <button onClick={() => setIsCustomerModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow flex items-center gap-2"><UserPlusIcon className="w-4 h-4"/> Add Customer</button>}
                 </div>
            </div>

            <div className="mb-6 border-b border-gray-200 dark:border-gray-700 flex justify-between items-end">
                <nav className="-mb-px flex space-x-6 overflow-x-auto">
                    {tabs.map(tab => <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`${activeTab === tab.id ? 'border-blue-500 text-blue-600 dark:text-blue-400' : 'border-transparent text-gray-500 dark:text-gray-400'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm focus:outline-none`}>{tab.label}</button>)}
                </nav>
                 <div className="mb-2 relative hidden sm:block"><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="pl-8 pr-4 py-1 text-sm border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md w-64" /><SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" /></div>
            </div>

            <div>
                {activeTab === 'Stock' && (
                     <div id="profile-stock-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                        <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                            <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                                <tr>
                                    <th className="px-6 py-3">Brand</th><th className="px-6 py-3">SKU</th><th className="px-6 py-3">Profile Name</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Stock</th><th className="px-6 py-3 text-center">Status</th>{canManage && <th className="px-6 py-3 text-right">Edit</th>}
                                </tr>
                            </thead>
                            <tbody>
                                {stockData.map(p => (
                                    <tr key={p.id} className="bg-white dark:bg-gray-800 border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                                        <td className="px-6 py-4">{getBrandBadge(p.brand)}</td><td className="px-6 py-4 font-medium">{p.sku}</td><td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{p.name}</td><td className="px-6 py-4 text-xs text-gray-500">{p.length}m | {p.weight}kg</td>
                                        <td className="px-6 py-4 text-right"><span className="font-bold text-blue-600 text-lg">{p.currentStock}</span> {p.reservedStock > 0 && <span className="text-xs text-orange-500 block">(-{p.reservedStock} Rsrvd)</span>}</td><td className="px-6 py-4 text-center">{p.currentStock < (p.reorderPoint || 0) ? <span className="text-red-500 font-bold">Low</span> : <span className="text-green-500">OK</span>}</td>
                                        {canManage && <td className="px-6 py-4 text-right"><button onClick={() => setEditingProfile(p)} className="text-blue-500 hover:underline">Edit</button></td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
                {activeTab === 'Planning' && (
                     <div id="profile-planning-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                        <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                            <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                                <tr>
                                    <th className="px-6 py-3">Brand</th><th className="px-6 py-3">SKU</th><th className="px-6 py-3">Profile Name</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Current Stock</th><th className="px-6 py-3 text-right">{planningTimeFilter === 'ALL' ? 'All Time Sales' : `Sales (${planningTimeFilter})`}</th><th className="px-6 py-3 text-right">Share %</th>
                                </tr>
                            </thead>
                            <tbody>
                                {planningData.map(p => (
                                    <tr key={p.id} className="bg-white dark:bg-gray-800 border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                                        <td className="px-6 py-4">{getBrandBadge(p.brand)}</td><td className="px-6 py-4 font-medium">{p.sku}</td><td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{p.name}</td><td className="px-6 py-4 text-xs text-gray-500">{p.length}m | {p.weight}kg</td>
                                        <td className="px-6 py-4 text-right font-bold text-gray-800 dark:text-gray-200">{p.currentStock}</td>
                                        <td className="px-6 py-4 text-right text-blue-600 dark:text-blue-400">{p.periodSales}</td>
                                        <td className="px-6 py-4 text-right">
                                            <div className="flex flex-col items-end">
                                                <span className="text-xs font-bold text-gray-700 dark:text-gray-300">{p.sharePercentage.toFixed(1)}%</span>
                                                <div className="w-24 h-1.5 bg-gray-200 dark:bg-gray-600 rounded-full mt-1">
                                                    <div className="h-1.5 bg-blue-500 rounded-full" style={{ width: `${Math.min(p.sharePercentage, 100)}%` }}></div>
                                                </div>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
                {(activeTab === 'Production' || activeTab === 'Dispatch') && (
                    <div id={`profile-${activeTab.toLowerCase()}-table`} className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                        <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                             <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                                <tr><th className="px-6 py-3">Date</th><th className="px-6 py-3">Ref No</th><th className="px-6 py-3">Profile</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Quantity</th>{activeTab === 'Dispatch' && <th className="px-6 py-3">Customer</th>}{canManage && <th className="px-6 py-3 text-right">Actions</th>}</tr>
                            </thead>
                            <tbody>
                                {(activeTab === 'Production' ? productionData : dispatchData).map(t => (
                                    <tr key={t.id} className="bg-white dark:bg-gray-800 border-b dark:border-gray-700">
                                        <td className="px-6 py-4">{new Date(t.date).toLocaleDateString()}</td><td className="px-6 py-4 font-medium">{t.refNo}</td><td className="px-6 py-4">{getProfileName(t.profileId)}</td><td className="px-6 py-4 text-xs text-gray-500">{getProfileSpecs(t.profileId)}</td><td className={`px-6 py-4 text-right font-semibold ${activeTab === 'Production' ? 'text-green-600' : 'text-red-600'}`}>{t.quantity}</td>{activeTab === 'Dispatch' && <td className="px-6 py-4">{t.customer}</td>}{canManage && <td className="px-6 py-4 text-right space-x-3"><button onClick={() => setEditingTransaction(t)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => deleteProfileTransaction(t.id)} className="text-red-500 hover:underline">Delete</button></td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
                {activeTab === 'Scrap' && (
                    <div id="profile-scrap-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                         <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                             <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                                <tr><th className="px-6 py-3">Date</th><th className="px-6 py-3">Ref No</th><th className="px-6 py-3">Profile</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Quantity</th><th className="px-6 py-3">Machine</th><th className="px-6 py-3">Die</th>{canManage && <th className="px-6 py-3 text-right">Actions</th>}</tr>
                            </thead>
                            <tbody>
                                {scrapData.map(t => (
                                    <tr key={t.id} className="bg-white dark:bg-gray-800 border-b dark:border-gray-700">
                                        <td className="px-6 py-4">{new Date(t.date).toLocaleDateString()}</td><td className="px-6 py-4 font-medium">{t.refNo}</td><td className="px-6 py-4">{getProfileName(t.profileId)}</td><td className="px-6 py-4 text-xs text-gray-500">{getProfileSpecs(t.profileId)}</td><td className="px-6 py-4 text-right font-semibold text-red-600">{t.quantity}</td><td className="px-6 py-4">{t.machine || '-'}</td><td className="px-6 py-4">{t.die || '-'}</td>
                                        {canManage && <td className="px-6 py-4 text-right space-x-3"><button onClick={() => setEditingTransaction(t)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => deleteProfileTransaction(t.id)} className="text-red-500 hover:underline">Delete</button></td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
                {activeTab === 'Quotations' && (
                    <div id="profile-quotation-table" className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                        <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                            <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                                <tr><th className="px-6 py-3">Date</th><th className="px-6 py-3">Ref No</th><th className="px-6 py-3">Customer</th><th className="px-6 py-3">Profile</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Qty</th><th className="px-6 py-3 text-center">Status</th>{canManage && <th className="px-6 py-3 text-center">Confirm</th>}{canManage && <th className="px-6 py-3 text-right">Actions</th>}</tr>
                            </thead>
                            <tbody>
                                {quotationData.map(t => (
                                    <tr key={t.id} className={`bg-white dark:bg-gray-800 border-b dark:border-gray-700 ${t.status === 'CANCELLED' ? 'opacity-50' : ''}`}>
