                                </tr>
                            </thead>
                            <tbody>
                                {filteredProfiles.map(p => (
                                    <tr key={p.id} className="bg-white dark:bg-gray-800 border-b dark:border-gray-700">
                                        <td className="px-6 py-4">{getBrandBadge(p.brand)}</td>
                                        <td className="px-6 py-4">{p.sku}</td>
                                        <td className="px-6 py-4">{p.name}</td>
                                        <td className="px-6 py-4">{p.uom}</td>
                                        <td className="px-6 py-4">{p.length || '-'}</td>
                                        <td className="px-6 py-4">{p.weight || '-'}</td>
