const EditProfileModal: React.FC<{ isOpen: boolean; onClose: () => void; profile: Profile | null; brands: string[]; onUpdate: (p: Profile) => void; addToast: any; }> = ({ isOpen, onClose, profile, brands, onUpdate }) => {
    const [form, setForm] = useState({ sku: '', name: '', brand: '', uom: 'Pcs', length: '', piecesPerPacket: '', weight: '', price: '', reorderPoint: '' });

    useEffect(() => {
        if (profile) {
            setForm({
                sku: profile.sku || '',
