const TransactionTable: React.FC<any> = ({ transactions, getProfileName, getProfileSpecs, onEdit, onDelete, type }) => (
    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
            <tr><th className="px-6 py-3">Date</th><th className="px-6 py-3">Ref No</th><th className="px-6 py-3">Profile</th><th className="px-6 py-3">Specs</th><th className="px-6 py-3 text-right">Quantity</th>{type === 'DISPATCH' && <th className="px-6 py-3">Customer</th>}{type === 'SCRAP' && <><th className="px-6 py-3">Machine</th><th className="px-6 py-3">Die</th></>}<th className="px-6 py-3 text-right">Actions</th></tr>
