                    <td className="px-6 py-4 text-right space-x-2"><button onClick={() => onEdit(t)} className="text-blue-500 hover:underline">Edit</button><button onClick={() => onDelete(t.id)} className="text-red-500 hover:underline">Del</button></td>
                </tr>
            ))}
        </tbody>
