const ProcessLogSheetModal: React.FC<{ isOpen: boolean, onClose: () => void, die: Die | null, onSave: (d: Die) => void, addToast: any }> = ({ isOpen, onClose, die, onSave, addToast }) => {
    // IMPORTANT: Use deep copy to initialize state to prevent mutation of original die object before saving
    const [data, setData] = useState<ProcessLogSheetData>({});

    useEffect(() => {
        if (die) setData(JSON.parse(JSON.stringify(die.processLog || {})));
    }, [die]);

    const generateLogSheetPdf = () => {
        if (!die) return;
        const { jsPDF } = jspdf;
        const doc = new jsPDF();
        const margin = 10;
        const pageWidth = doc.internal.pageSize.getWidth();

        doc.setFontSize(16);
        doc.setFont('helvetica', 'bold');
        doc.text('PROCESS LOG SHEET', pageWidth / 2, margin + 5, { align: 'center' });

        let y = margin + 15;
        doc.setFontSize(10);
        doc.setFont('helvetica', 'normal');
        const headerData = [
            ['Date :', data.date || '', 'PROFILE SPPED IN MINS :', data.profileSpeed || ''],
            ['Machine No :', data.machineNo || '', 'OUTPUT PER HOUR :', data.outputPerHour || ''],
            ['Tool ID :', data.toolId || '', 'Profile Colour :', data.profileColour || ''],
            ['Tool Man :', data.toolMan || '', '', ''],
        ];
        headerData.forEach(row => {
            doc.text(row[0], margin, y);
            doc.text(row[1], margin + 45, y);
            doc.text(row[2], margin + 100, y);
            doc.text(row[3], margin + 145, y);
            y += 6;
        });

        const tableBody: any[] = [];
        const addRow = (sno: string, label: string, val1: string, val2: string = '') => tableBody.push([sno, label, val1, val2]);
        const addSection = (sno: string, label: string) => tableBody.push([{ content: sno, styles: { fontStyle: 'bold' } }, { content: label, colSpan: 3, styles: { fontStyle: 'bold', fillColor: '#f3f4f6' } }]);

        addSection('1', 'Barrel Temp : Act / Set OC');
        const bt = data.barrelTemp || {};
        addRow('', 'BZ - 1', bt.bz1?.act || '', bt.bz1?.set || '');
        addRow('', 'BZ - 2', bt.bz2?.act || '', bt.bz2?.set || '');
        addRow('', 'BZ - 3', bt.bz3?.act || '', bt.bz3?.set || '');
        addRow('', 'BZ - 4', bt.bz4?.act || '', bt.bz4?.set || '');
        addRow('', 'BZ - 5', bt.bz5?.act || '', bt.bz5?.set || '');
        addRow('', 'BZ - 6', bt.bz6?.act || '', bt.bz6?.set || '');
        addRow('', 'C/H-1', bt.ch1?.act || '', bt.ch1?.set || '');
        addRow('', 'C/H-2', bt.ch2?.act || '', bt.ch2?.set || '');

        addSection('2', 'Tooling Temp : Act/Sec OC');
        const tt = data.toolingTemp || {};
        addRow('', 'DZ - 1', tt.dz1?.act || '', tt.dz1?.set || '');
        addRow('', 'DZ - 2', tt.dz2?.act || '', tt.dz2?.set || '');
        addRow('', 'DZ - 3', tt.dz3?.act || '', tt.dz3?.set || '');
        addRow('', 'DZ - 4', tt.dz4?.act || '', tt.dz4?.set || '');

        const addSingleParam = (sno: string, label: string, value: string) => tableBody.push([sno, { content: label, colSpan: 1 }, { content: value, colSpan: 2 }]);
        addSingleParam('3', 'Extruder: RPM', data.extruderRpm || '');
        addSingleParam('4', 'Screw Torque (%)', data.screwTorque || '');
        addSingleParam('5', 'Feeder - 01 Blend', data.feederBlend || '');
        addSingleParam('6', 'Haul Off: RPM', data.haulOffRpm || '');
        addSingleParam('7', 'Melt Temp', data.meltTemp || '');
        addSingleParam('8', 'Melt Pressure : Bar', data.meltPressure || '');
        addSingleParam('9', 'Degasing: mm Of hg', data.degasing || '');

        addSection('10', 'Calibrator');
        const cal = data.calibrator || {};
        addSingleParam('', 'Vaccum - 1 : Bar', cal.vacuum1 || '');
        addSingleParam('', 'Vaccum - 2 : Bar', cal.vacuum2 || '');
        addSingleParam('', 'Vaccum - 3 : Bar', cal.vacuum3 || '');
        addSingleParam('', 'Vaccum - 4 : Bar', cal.vacuum4 || '');
        addSingleParam('', 'Vaccum - 5 : Bar', cal.vacuum5 || '');
        addSingleParam('', 'Water Temp : OC', cal.waterTemp || '');
        addSingleParam('', 'Water Pressure : Bar', cal.waterPressure || '');

        addSection('11', 'Cooling Tank');
        const ct = data.coolingTank || {};
        addSingleParam('', 'Vaccum - L/R', ct.vacuumLR1 || '');
        addSingleParam('', 'Vaccum - L/R', ct.vacuumLR2 || '');
        addSingleParam('', 'Vaccum - L/R', ct.vacuumLR3 || '');

        addSingleParam('12', 'Haul Off : Pressure (Bar)', data.haulOffPressure || '');
        addSingleParam('13', 'Counter (Bar)', data.counter || '');
        addSingleParam('14', 'Cutter : Clamping (Bar)', data.cutterClamping || '');
        addSingleParam('15', 'Time of Tripping (Min)', data.timeOfTripping || '');
        addSingleParam('16', 'Signature of Operator', data.signatureOperator || '');
        addSingleParam('17', 'Signature of Engineer', data.signatureEngineer || '');
        addSingleParam('18', 'Remarks', data.remarks || '');

        doc.autoTable({
            startY: y + 5,
            head: [['S.NO', 'Parameter', 'Actual', 'Set']],
            body: tableBody,
            theme: 'grid',
            headStyles: { fontStyle: 'bold' },
            columnStyles: { 0: { cellWidth: 15 }, 1: { cellWidth: 'auto' }, 2: { cellWidth: 40 }, 3: { cellWidth: 40 } }
        });

        doc.save(`ProcessLog_${die.dieNo}.pdf`);
    };

    if (!isOpen || !die) return null;

    const handleHeaderChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const handleParamChange = (group: keyof ProcessLogSheetData, param: string, value: string) => {
        setData(prev => {
            const newData = { ...prev };
            // @ts-ignore
            if (!newData[group]) newData[group] = {};
            // @ts-ignore
            newData[group] = { ...newData[group], [param]: value };
            return newData;
        });
    };

    const handleTempChange = (group: keyof ProcessLogSheetData, param: string, type: 'act' | 'set', value: string) => {
        setData(prev => {
            const newData = { ...prev };
            // @ts-ignore
            if (!newData[group]) newData[group] = {};
            // @ts-ignore
            if (!newData[group][param]) newData[group][param] = {};
            // @ts-ignore
            newData[group][param] = { ...newData[group][param], [type]: value };
            return newData;
        });
    };

    const handleSubmit = () => {
        onSave({ ...die, processLog: data });
        addToast('Process Log Sheet Saved!', 'success');
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-70 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-6xl max-h-[90vh] flex flex-col" onClick={e => e.stopPropagation()}>
                <div className="p-4 border-b dark:border-gray-700">
                    <h2 className="text-xl font-bold text-center">PROCESS LOG SHEET</h2>
                </div>
                <div className="p-4 overflow-y-auto">
                    <table className="w-full text-sm mb-4"><tbody>
                        <tr>
                            <td className="font-semibold p-1"><label htmlFor="log-date">Date :</label></td><td className="p-1"><input id="log-date" type="date" name="date" value={data.date || ''} onChange={handleHeaderChange} className="w-full bg-gray-50 dark:bg-gray-700 p-1 rounded border dark:border-gray-600"/></td>
                            <td className="font-semibold p-1"><label htmlFor="log-profileSpeed">PROFILE SPEED (MINS) :</label></td><td className="p-1"><input id="log-profileSpeed" name="profileSpeed" value={data.profileSpeed || ''} onChange={handleHeaderChange} className="w-full bg-gray-50 dark:bg-gray-700 p-1 rounded border dark:border-gray-600"/></td>
                        </tr>
                        <tr>
                            <td className="font-semibold p-1"><label htmlFor="log-machineNo">Machine No :</label></td><td className="p-1"><input id="log-machineNo" name="machineNo" value={data.machineNo || ''} onChange={handleHeaderChange} className="w-full bg-gray-50 dark:bg-gray-700 p-1 rounded border dark:border-gray-600"/></td>
                            <td className="font-semibold p-1"><label htmlFor="log-outputPerHour">OUTPUT PER HOUR :</label></td><td className="p-1"><input id="log-outputPerHour" name="outputPerHour" value={data.outputPerHour || ''} onChange={handleHeaderChange} className="w-full bg-gray-50 dark:bg-gray-700 p-1 rounded border dark:border-gray-600"/></td>
                        </tr>
                        <tr>
                            <td className="font-semibold p-1"><label htmlFor="log-toolId">Tool ID :</label></td><td className="p-1"><input id="log-toolId" name="toolId" value={data.toolId || ''} onChange={handleHeaderChange} className="w-full bg-gray-50 dark:bg-gray-700 p-1 rounded border dark:border-gray-600"/></td>
                            <td className="font-semibold p-1"><label htmlFor="log-profileColour">Profile Colour :</label></td><td className="p-1"><input id="log-profileColour" name="profileColour" value={data.profileColour || ''} onChange={handleHeaderChange} className="w-full bg-gray-50 dark:bg-gray-700 p-1 rounded border dark:border-gray-600"/></td>
                        </tr>
                        <tr>
                            <td className="font-semibold p-1"><label htmlFor="log-toolMan">Tool Man :</label></td><td className="p-1"><input id="log-toolMan" name="toolMan" value={data.toolMan || ''} onChange={handleHeaderChange} className="w-full bg-gray-50 dark:bg-gray-700 p-1 rounded border dark:border-gray-600"/></td>
                        </tr>
                    </tbody></table>

                    <table className="w-full text-sm border-collapse border dark:border-gray-600">
                        <thead className="bg-gray-100 dark:bg-gray-700">
                            <tr><th className="px-2 py-1 border dark:border-gray-600 w-12">S.NO</th><th className="px-2 py-1 border dark:border-gray-600">Parameter</th><th className="px-2 py-1 border dark:border-gray-600">Actual</th><th className="px-2 py-1 border dark:border-gray-600">Set</th></tr>
                        </thead>
