interface ManageBrandsModalProps {
    isOpen: boolean;
    onClose: () => void;
    brands: string[];
    addBrand: (brand: string) => void;
    updateBrand: (oldB: string, newB: string) => void;
    deleteBrand: (brand: string) => void;
    addToast: (message: string, type: ToastMessage['type']) => void;
}

const ManageBrandsModal: React.FC<ManageBrandsModalProps> = ({ isOpen, onClose, brands, addBrand, deleteBrand, addToast }) => {
    const [newB, setNewB] = useState('');
    const [editingBrand, setEditingBrand] = useState<{ id: string, name: string } | null>(null);
    const [editName, setEditName] = useState('');

    useEffect(() => {
        if (isOpen) {
            setNewB('');
            setEditingBrand(null);
            setEditName('');
        }
    }, [isOpen]);

    if (!isOpen) return null;

    const handleAdd = () => { 
        if (newB.trim() && !brands.includes(newB.trim())) { 
            addBrand(newB.trim()); 
            setNewB(''); 
            addToast(`Brand "${newB.trim()}" added.`, 'success');
        } else if (newB.trim()) { 
            addToast('Brand already exists.', 'error'); 
        }
    };

    const handleEditStart = (brand: string) => {
        setEditingBrand({ id: brand, name: brand });
        setEditName(brand);
    };

    const handleEditSave = () => {
        if (!editingBrand) return;
        if (editName.trim() === editingBrand.name) { // No change
            setEditingBrand(null);
            setEditName('');
            return;
        }
        if (editName.trim() && !brands.includes(editName.trim())) {
            updateBrand(editingBrand.name, editName.trim());
            addToast(`Brand "${editingBrand.name}" updated to "${editName.trim()}".`, 'success');
            setEditingBrand(null);
            setEditName('');
        } else if (editName.trim()) {
            addToast('Brand name is empty or already exists.', 'error');
        }
    };

    const handleDelete = (e: React.MouseEvent, brand: string) => { 
        e.stopPropagation(); // Prevent modal closing
        deleteBrand(brand);
        addToast(`Brand "${brand}" deleted.`, 'info');
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg w-full max-w-sm" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold mb-4 dark:text-white">Manage Brands</h3>
                <div className="flex gap-2 mb-4">
                    <input 
                        value={newB} 
                        onChange={e => setNewB(e.target.value)} 
                        className="border p-2 flex-1 rounded dark:bg-gray-700 dark:text-white dark:border-gray-600"
                        placeholder="New Brand Name"
                        onKeyPress={(e) => { if (e.key === 'Enter') { e.preventDefault(); handleAdd(); } }}
                    />
                    <button onClick={handleAdd} className="bg-blue-600 text-white px-4 py-2 rounded">Add</button>
                </div>
                <div className="max-h-48 overflow-y-auto border rounded dark:border-gray-600">
                    {brands.map((b:string) => (
                        <div key={b} className="flex justify-between p-2 border-b dark:border-gray-700 dark:text-gray-200 items-center">
                            {editingBrand?.id === b ? (
                                <input 
                                    type="text"
                                    value={editName}
                                    onChange={e => setEditName(e.target.value)}
                                    onBlur={handleEditSave} // Save on blur
                                    onKeyPress={(e) => { if (e.key === 'Enter') { e.preventDefault(); handleEditSave(); } }}
                                    className="flex-1 bg-gray-50 dark:bg-gray-700 p-1 rounded border dark:border-gray-600"
                                    autoFocus
                                />
                            ) : (
                                <span>{b}</span>
                            )}
                            <div className="space-x-2">
                                {editingBrand?.id !== b && (
                                    <button onClick={() => handleEditStart(b)} className="text-blue-500 hover:text-blue-700"><PencilIcon className="w-4 h-4" /></button>
                                )}
                                <button onClick={(e) => handleDelete(e, b)} className="text-red-500 hover:text-red-700">Del</button>
                            </div>
                        </div>
                    ))}
                </div>
                <button onClick={onClose} className="mt-4 w-full border p-2 rounded dark:text-white">Close</button>
            </div>
        </div>
    );
};

