import React, { useState, useCallback, useMemo } from 'react';
import { GoogleGenAI, Type } from '@google/genai';
import type { InflowTransaction, ToastMessage } from '../types';
import Card from '../components/Card';

declare const XLSX: any;

interface ImportExcelProps {
    addMultipleInflowTransactions: (transactions: (Omit<InflowTransaction, 'id' | 'createdAt' | 'totalCost' | 'itemId'> & { sku: string, name?: string })[]) => void;
    addToast: (message: string, type: ToastMessage['type']) => void;
}

type ImportType = 'inflow'; // Hardcoded to inflow

const ERP_FIELDS = {
    inflow: {
        sku: { label: 'SKU / Item Code', required: true },
        quantity: { label: 'Quantity', required: true },
        unitCost: { label: 'Unit Cost', required: true },
        name: { label: 'Item Name', required: false },
        supplier: { label: 'Supplier', required: false },
        refNo: { label: 'Reference No.', required: false },
        txnDate: { label: 'Transaction Date', required: false },
    }
};

const ALL_HEADER_ALIASES: { [key: string]: string[] } = {
    sku: ['sku', 'item code', 'product code', 'material no', 'part no', 'item number'],
    name: ['name', 'item name', 'product name', 'description'],
    quantity: ['quantity', 'qty', 'units', 'pcs', 'unit in kg', 'unit'],
    unitCost: ['unit cost', 'cost price', 'price per unit', 'cost', 'rate'],
    supplier: ['supplier', 'vendor'],
    refNo: ['ref no', 'reference no', 'po no', 'order no', 'invoice no'],
    txnDate: ['date', 'transaction date', 'txn date', 'order date'],
};

const NORMALIZED_ALIASES = new Set(
    Object.values(ALL_HEADER_ALIASES).flat().map(alias => alias.replace(/[^a-z0-9]/g, ''))
);

// Helper to safely access API key without crashing if process is undefined
const getApiKey = () => {
    try {
        return (typeof process !== 'undefined' && process.env && process.env.API_KEY) || '';
    } catch (e) {
        return '';
    }
};

const ImportExcel: React.FC<ImportExcelProps> = ({ addMultipleInflowTransactions, addToast }) => {
    const [files, setFiles] = useState<File[]>([]);
    const [parsedData, setParsedData] = useState<any[]>([]);
    const [detectedHeaders, setDetectedHeaders] = useState<string[]>([]);
    const [columnMapping, setColumnMapping] = useState<Record<string, string | null>>({});

    const [isLoading, setIsLoading] = useState(false);
    const [statusMessage, setStatusMessage] = useState('');

    const [currentStep, setCurrentStep] = useState<'upload' | 'map'>('upload');
    const importType: ImportType = 'inflow';

    const ai = useMemo(() => new GoogleGenAI({ apiKey: getApiKey() }), []);

    const resetState = useCallback(() => {
        setFiles([]);
        setParsedData([]);
        setDetectedHeaders([]);
        setColumnMapping({});
        setCurrentStep('upload');
        setStatusMessage('');
        const fileInput = document.getElementById('file-upload') as HTMLInputElement;
        if(fileInput) fileInput.value = '';
    }, []);

    const handleAutoMapColumns = useCallback(async (headers: string[]) => {
        setIsLoading(true);
        setStatusMessage('Mapping columns...');

        const normalize = (s: string) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

        const fieldsToMap = ERP_FIELDS.inflow;
        const erpFields = Object.keys(fieldsToMap);
        const initialMapping: Record<string, string | null> = {};
        const unmappedHeaders = [...headers];

        // 1. Deterministic Pass
        erpFields.forEach(erpField => {
            initialMapping[erpField] = null;
            const aliases = ALL_HEADER_ALIASES[erpField] || [];
            for (const alias of aliases) {
                const normalizedAlias = normalize(alias);
                const foundHeader = unmappedHeaders.find(h => normalize(h) === normalizedAlias);
                if (foundHeader) {
                    initialMapping[erpField] = foundHeader;
                    unmappedHeaders.splice(unmappedHeaders.indexOf(foundHeader), 1);
                    break; 
                }
            }
        });

        const unmappedErpFields = erpFields.filter(field => !initialMapping[field]);

        // 2. AI Pass (only if needed for remaining fields)
        if (unmappedErpFields.length > 0 && unmappedHeaders.filter(h => !h.startsWith('__EMPTY')).length > 0) {
            setStatusMessage('Using AI to map remaining columns...');
            try {
                const fieldsSchema: Record<string, { type: Type, description: string }> = {};
                unmappedErpFields.forEach(field => {
                    fieldsSchema[field] = { type: Type.STRING, description: `The header from the user's file that maps to ${field}. Should be one of [${unmappedHeaders.join(', ')}] or null.` };
                });

                const prompt = `You are an expert data mapping assistant for an ERP system. Your task is to map remaining ambiguous column headers to the ERP's fields.
The user is importing an 'inflow' transaction.
Some fields were already mapped. We need to map these remaining ERP fields: ${unmappedErpFields.join(', ')}.
Here are the remaining unmapped headers from the user's file: ${JSON.stringify(unmappedHeaders)}
Analyze the unmapped headers and determine which one maps to each of the unmapped ERP fields. It is critical that you are accurate. If you cannot find a confident match for a field, use the value null.
Return a JSON object with the unmapped ERP fields as keys and the corresponding user header as the value.`;

                const response = await ai.models.generateContent({
                    model: 'gemini-2.5-flash',
                    contents: prompt,
                    config: {
                        responseMimeType: 'application/json',
                        responseSchema: { type: Type.OBJECT, properties: fieldsSchema }
                    }
                });

                const aiMappingResult = JSON.parse(response.text);

                unmappedErpFields.forEach(field => {
                    const mappedHeader = aiMappingResult[field];
                    if (mappedHeader && unmappedHeaders.includes(mappedHeader)) {
                        initialMapping[field] = mappedHeader;
                    }
                });

                setStatusMessage('AI mapping complete. Please review the results.');

            } catch (error) {
                console.error('AI mapping assist failed:', error);
                setStatusMessage('AI assist failed. Please map remaining columns manually.');
            }
        } else {
             setStatusMessage('Mapping complete. Please review the results.');
        }

        setColumnMapping(initialMapping);
        setIsLoading(false);
        setCurrentStep('map');

    }, [ai]);

    const handleFileParse = useCallback(async () => {
        if (files.length === 0) return;
        setIsLoading(true);
        setStatusMessage('Parsing file...');
        const file = files[0];
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = XLSX.read(data, { type: 'array' });
                const sheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[sheetName];
                const rows = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: null });

                if (rows.length === 0) throw new Error("The selected file is empty.");

                let headerRowIndex = -1;
                let maxMatchCount = 0;

                for (let i = 0; i < Math.min(rows.length, 10); i++) {
                    const row = (rows[i] as any[]) || [];
                    if (row.filter(cell => cell !== null && String(cell).trim() !== '').length < 2) continue;

                    let currentMatchCount = 0;
                    for (const cell of row) {
                       const normalizedCell = String(cell || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                       if (NORMALIZED_ALIASES.has(normalizedCell)) {
                           currentMatchCount++;
                       }
                    }

                    if (currentMatchCount > maxMatchCount && currentMatchCount >= 2) {
                        maxMatchCount = currentMatchCount;
                        headerRowIndex = i;
                    }
                }

                if (headerRowIndex === -1) {
                    throw new Error("Could not automatically detect the header row. Please ensure your file has a row with column titles like 'SKU' and 'Quantity' within the first 10 rows.");
                }

                const headerRow: string[] = (rows[headerRowIndex] as any[]).map(h => String(h || '').trim());
                const uniqueHeaders = headerRow.map((h, i) => h || `__EMPTY_${i}`);
                const dataRows = rows.slice(headerRowIndex + 1);

                const jsonData = dataRows.map(rowArray => {
                    const obj: { [key: string]: any } = {};
                    uniqueHeaders.forEach((header, index) => { obj[header] = (rowArray as any[])[index]; });
                    return obj;
                }).filter(obj => Object.values(obj).some(val => val !== null && String(val).trim() !== ''));

                if (jsonData.length === 0) throw new Error("No data rows were found after the header row.");

                setParsedData(jsonData);
                setDetectedHeaders(uniqueHeaders);
                handleAutoMapColumns(uniqueHeaders);

            } catch (error: any) {
                console.error("Error parsing file:", error);
                addToast(`Error: ${error.message}`, 'error');
                resetState();
            }
        };
        reader.onerror = () => {
             addToast("Error reading the file.", 'error');
             resetState();
        };
        reader.readAsArrayBuffer(file);
    }, [files, handleAutoMapColumns, resetState, addToast]);

    const handleMappingChange = (erpField: string, fileHeader: string | null) => {
        setColumnMapping(prev => ({ ...prev, [erpField]: fileHeader === '__ignore__' ? null : fileHeader }));
    };

    const handleImport = () => {
        const currentFields = ERP_FIELDS.inflow;
        const requiredFields = Object.keys(currentFields).filter(f => currentFields[f as keyof typeof currentFields].required);
        const missingMappings = requiredFields.filter(field => !columnMapping[field]);

        if (missingMappings.length > 0) {
            addToast(`Import failed. Please map: ${missingMappings.map(f => currentFields[f as keyof typeof currentFields].label).join(', ')}.`, 'error');
            return;
        }

        const mappedData = parsedData.map(row => {
            const newRow: Record<string, any> = {};
            for (const erpField in columnMapping) {
                const fileHeader = columnMapping[erpField];
                if (fileHeader) {
                    newRow[erpField] = row[fileHeader];
                }
            }
            return newRow;
        });

        const txnsToImport = mappedData.map(row => {
            const quantity = parseFloat(row.quantity);
            const unitCost = parseFloat(row.unitCost);
            if (!row.sku || isNaN(quantity) || quantity <= 0 || isNaN(unitCost) || unitCost < 0) return null;
            return {
                sku: String(row.sku),
                name: row.name ? String(row.name) : undefined,
                quantity, unitCost,
                supplier: String(row.supplier || ''),
                refNo: String(row.refNo || ''),
                txnDate: row.txnDate ? new Date(row.txnDate).toISOString() : new Date().toISOString(),
            };
        }).filter(Boolean) as any[];
        addMultipleInflowTransactions(txnsToImport);

        resetState();
    };

    return (
        <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-6">Import Inflow Transactions</h1>
            <Card>
                {isLoading ? (
                    <div className="text-center p-12">
                        <p className="text-lg font-semibold">{statusMessage}</p>
                        <p className="text-gray-500 mt-2">Please wait...</p>
                    </div>
                ) : currentStep === 'upload' ? (
                    <UploadStep setFiles={setFiles} files={files} onProceed={handleFileParse} />
                ) : (
                    <MappingStep 
                        detectedHeaders={detectedHeaders}
                        columnMapping={columnMapping}
                        onMappingChange={handleMappingChange}
                        onConfirm={handleImport}
                        onCancel={resetState}
                        previewData={parsedData}
                    />
                )}
            </Card>
        </div>
    );
};

const UploadStep = ({ setFiles, files, onProceed }: any) => {
    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        if (event.target.files) {
            setFiles(Array.from(event.target.files));
        }
    };
    return (
        <>
            <div>
                <h3 className="text-md font-semibold text-gray-700 dark:text-gray-200 mb-2">Upload Inflow File</h3>
                <label htmlFor="file-upload" className="border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-12 text-center cursor-pointer hover:border-blue-500 transition-colors block focus-within:ring-2 focus-within:ring-blue-500">
                    <input id="file-upload" type="file" className="hidden" accept=".xlsx, .xls, .csv" onChange={handleFileChange} />
                    <p className="text-gray-500">{files[0]?.name || "Drag & drop a file here, or click to select"}</p>
                    <p className="text-xs text-gray-400 mt-1">Supports .xlsx, .xls, .csv</p>
                </label>
            </div>
            {files.length > 0 && (
                <div className="mt-6 flex justify-end">
                    <button onClick={onProceed} className="bg-blue-600 text-white px-6 py-2 rounded-md font-semibold hover:bg-blue-700 shadow">Next: Map Columns</button>
                </div>
            )}
        </>
    );
};

const MappingStep = ({ detectedHeaders, columnMapping, onMappingChange, onConfirm, onCancel, previewData }: any) => {
    const fields = ERP_FIELDS.inflow;

    return (
        <div>
            <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Map Columns for Inflow</h2>
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-6">Review the AI-powered column mapping. Ensure each required field (marked with *) is correctly mapped to a column from your file.</p>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-6 gap-y-4 mb-8">
                {Object.entries(fields).map(([fieldKey, fieldInfo]: [string, any]) => (
                    <div key={fieldKey}>
                        <label htmlFor={`map-${fieldKey}`} className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                            {fieldInfo.label} {fieldInfo.required && <span className="text-red-500">*</span>}
                        </label>
                        <select 
                            id={`map-${fieldKey}`} 
                            value={columnMapping[fieldKey] || '__ignore__'}
                            onChange={e => onMappingChange(fieldKey, e.target.value)}
                            className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 dark:bg-gray-700 dark:border-gray-600 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm rounded-md"
                        >
                            <option value="__ignore__">-- Not Mapped --</option>
                            {detectedHeaders.map((header: string) => (
                                <option key={header} value={header}>{header.startsWith('__EMPTY') ? `Unnamed Column ${header.split('_')[2]}` : header}</option>
                            ))}
                        </select>
                    </div>
                ))}
            </div>

            <h3 className="text-lg font-semibold text-gray-800 dark:text-gray-200 mb-4">Data Preview</h3>
            <div className="overflow-x-auto bg-white dark:bg-gray-800 rounded-md shadow max-h-96">
                 <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                    <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700 sticky top-0">
                        <tr>{detectedHeaders.map((h: string) => <th key={h} scope="col" className="px-6 py-3">{h.startsWith('__EMPTY') ? `Unnamed Column ${h.split('_')[2]}`: h}</th>)}</tr>
                    </thead>
                    <tbody>
                        {previewData.slice(0, 10).map((row: any, index: number) => (
                            <tr key={index} className="bg-white dark:bg-gray-800 border-b dark:border-gray-700">
                                {detectedHeaders.map((header: string) => <td key={header} className="px-6 py-4 whitespace-nowrap">{String(row[header] ?? '')}</td>)}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            {previewData.length > 10 && <p className="text-xs text-gray-500 mt-2">Showing first 10 of {previewData.length} rows.</p>}

            <div className="mt-8 flex justify-between items-center">
                 <button onClick={onCancel} className="bg-gray-200 text-gray-800 px-5 py-2 rounded-md text-sm font-semibold hover:bg-gray-300 dark:bg-gray-600 dark:text-gray-200 dark:hover:bg-gray-500">Back to Upload</button>
                 <button onClick={onConfirm} className="bg-green-600 hover:bg-green-700 text-white px-8 py-2 rounded-md text-sm font-semibold shadow">
                    Confirm & Import {previewData.length} Records
                </button>
            </div>
        </div>
    );
};

export default ImportExcel;
