```tsx
export type ID = string;

export type Role = 'ADMIN' | 'MANAGER' | 'AGENT' | 'VIEWER'; 

export type Page = 'Dashboard' | 'RM Section' | 'Profile Section' | 'Dies & Planning' | 'History' | 'Storage' | 'Import' | 'Trash';

export interface User {
  id: ID; // Google User ID (sub) or a generic ID like 'guest'
  email?: string;
  name?: string;
  picture?: string; // URL to profile picture
  isGuest?: boolean;
  role: Role;
  isDriveConnected?: boolean;
}

export interface Warehouse {
  id: ID;
  name: string;
}

export interface CompanySettings {
    name: string;
    addressLine1: string;
    addressLine2: string;
    cityStateZip: string;
    gstin: string;
    phone: string;
    email: string;
    bankName?: string;
    accountNo?: string;
    ifsc?: string;
    branch?: string;
    logoUrl?: string; // Base64 or URL
    terms?: string;
    cgstRate?: number;
    sgstRate?: number;
    igstRate?: number;
}

export interface Customer {
    id: ID;
    name: string;
    address?: string;
    gstin?: string;
    phone?: string;
    createdAt: string;
    deletedAt?: string | null;
}

export interface Item {
  id: ID;
  sku: string;
  name:string;
  uom: string; // unit of measure
  description?: string;
  defaultWarehouseId?: ID;
  reorderPoint: number;
  preferredSupplier?: string;
  costPrice?: number;
  salesPrice?: number;
  createdAt: string;
  deletedAt?: string | null;
}

export interface Profile {
  id: ID;
  sku: string;
  name: string;
  uom: string; // e.g. 'pcs', 'meters'
  description?: string;
  length?: number; // meters
  piecesPerPacket?: number; // no. of lengths per packet
  weight?: number; // kg per piece
  price?: number; // Price per piece
  reorderPoint?: number; // low stock alert level
  brand?: string; // e.g. 'Scraft', 'Smart'
  hsnCode?: string;
  createdAt: string;
  deletedAt?: string | null;
}

export interface ProfileTransaction {
  id: ID;
  profileId: ID;
  type: 'PRODUCTION' | 'DISPATCH' | 'RETURN' | 'SCRAP' | 'QUOTATION';
  quantity: number;
  uom?: 'Pcs' | 'Kgs'; // For scrap recording
  date: string; // ISO
  refNo: string; 
  machine?: string; // For scrap/production
  die?: string; // For scrap/production

  // Quotation specific
  status?: 'PENDING' | 'COMPLETED' | 'CANCELLED';

  // Quotation/Dispatch specific
  customer?: string;
  customerAddress?: string;
  customerGST?: string;
  customerPhone?: string;

  createdAt: string;
  deletedAt?: string | null;
}

export interface ItemBatch {
  id: ID;
  itemId: ID;
  batchNo: string;
  receivedDate: string; // ISO
  expiryDate?: string; // ISO | null
  quantity: number;
  cost: number;
}

export interface InflowTransaction {
  id: ID;
  refNo: string;
  itemId: ID;
  batchId?: ID;
  quantity: number;
  unitCost: number;
  totalCost: number;
  warehouseId: ID;
  supplier?: string;
  createdBy?: ID;
  createdAt: string; // ISO
  txnDate: string; // ISO
  sourceDoc?: string;
  deletedAt?: string | null;
}

export interface ConsumptionTransaction {
  id: ID;
  refNo: string; // Production Reference
  itemId: ID;
  batchId?: ID;
  quantity: number;
  warehouseId: ID;
  batchNo?: string; // Production Reference
  createdBy?: ID;
  createdAt: string; // ISO
  txnDate: string; // ISO
  sourceDoc?: string;
  deletedAt?: string | null;
  type?: 'PROD' | 'SCRAP'; // Added for scrap tracking
}

export interface Formula {
  id: ID;
  name: string;
  outputProduct: string;
  outputQuantity: number;
  outputUom: string;
  ingredients: {
    itemId: ID;
    quantity: number;
  }[];
  createdAt: string;
  deletedAt?: string | null;
}

export interface TempParam {
    act?: string;
    set?: string;
}

export interface ProcessLogSheetData {
    // Header
    date?: string;
    machineNo?: string;
    toolId?: string;
    toolMan?: string;
    profileSpeed?: string;
    outputPerHour?: string;
    profileColour?: string;

    // Parameters
    barrelTemp?: {
        bz1?: TempParam; bz2?: TempParam; bz3?: TempParam; bz4?: TempParam;
        bz5?: TempParam; bz6?: TempParam; ch1?: TempParam; ch2?: TempParam;
    };
    toolingTemp?: {
        dz1?: TempParam; dz2?: TempParam; dz3?: TempParam; dz4?: TempParam;
    };
    extruderRpm?: string;
    screwTorque?: string;
    feederBlend?: string;
    haulOffRpm?: string;
    meltTemp?: string;
    meltPressure?: string;
    degasing?: string;
    calibrator?: {
        vacuum1?: string; vacuum2?: string; vacuum3?: string; vacuum4?: string;
        vacuum5?: string; waterTemp?: string; waterPressure?: string;
    };
    coolingTank?: {
        vacuumLR1?: string; vacuumLR2?: string; vacuumLR3?: string;
    };
    haulOffPressure?: string;
    counter?: string;
    cutterClamping?: string;
    timeOfTripping?: string;
    signatureOperator?: string;
    signatureEngineer?: string;
    remarks?: string;
}

export interface Die {
    id: ID;
    dieNo: string;
    profileId: ID;
    brand?: string; // Brand derived from Profile
    cavities: number;
    expectedOutputKgHr: number;
    lifespanMeters: number;
    status: 'ACTIVE' | 'INACTIVE' | 'MAINTENANCE';
    createdAt: string;
    deletedAt?: string | null;
    processLog?: ProcessLogSheetData; // Log sheet data
}

export interface ProductionPlan {
    id: ID;
    date: string; // ISO Date YYYY-MM-DD
    shift: 'A' | 'B' | 'C';
    machineNo: string;
    dieId: ID;
    targetMeters: number;
    createdAt: string;
    deletedAt?: string | null;
}


export interface ReportCorrection {
  itemId: ID;
  date: string; // YYYY-MM-DD format
  correctedInflow: number;
  correctedConsumption: number;
  reason: string;
  updatedAt: string; // ISO
}

export interface ToastMessage {
  id: number;
  message: string;
  type: 'success' | 'error' | 'info';
}

export interface ConfirmationState {
  isOpen: boolean;
  title: string;
  message: string;
  onConfirm: () => void;
}

export interface BatchForecastIngredient {
    itemId: ID;
    name: string;
    uom: string;
    requiredQty: number;
    availableStock: number;
    possibleBatches: number;
}

export interface BatchForecastResult {
    maxBatches: number;
    limitingIngredientId: ID | null;
    ingredientDetails: BatchForecastIngredient[];
    formula: Formula;
}
