```tsx
import React, { useState, useEffect, useRef, useMemo } from 'react';
import { createPortal } from 'react-dom';
import Card from '../components/Card';
import { WarningIcon, SparklesIcon, SpinnerIcon } from '../components/Icon';
import type { Item, Formula, BatchForecastResult, ToastMessage } from '../types';
import ItemListModal from '../components/ItemListModal';
import LowStockItemsModal from '../components/LowStockItemsModal';
import InventoryValueModal from '../components/InventoryValueModal';
import BatchCalculator from '../components/BatchCalculator';
import BatchForecastModal from '../components/BatchForecastModal';
import { GoogleGenAI } from '@google/genai';
import MarkdownRenderer from '../components/MarkdownRenderer';


declare const Chart: any;

// --- PORTAL COMPONENT ---
// This lifts the modals out of the current component's DOM tree and renders them at the top level (document.body).
// This is essential to bypass CSS stacking context issues caused by parent animations (like animate-fade-in-right).
const Portal: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    return createPortal(children, document.body);
};


interface DashboardStats {
    totalItems: number;
    lowStockItems: (Item & { currentStock: number })[];
    totalInventoryValue: number;
    inventoryValueDistribution: { name: string, value: number }[];
    monthlyOperations: { [key: string]: { inflow: number, consumption: number } };
    totalBatches: number;
}

interface DashboardProps {
    items: Item[];
    stockLevels: Record<string, number>;
    stats: DashboardStats;
    formulas: Formula[];
    addToast: (message: string, type: ToastMessage['type']) => void;
}

// Helper to safely access API key without crashing if process is undefined
const getApiKey = () => {
    try {
        return (typeof process !== 'undefined' && process.env && process.env.API_KEY) || '';
    } catch (e) {
        return '';
    }
};

const Dashboard: React.FC<DashboardProps> = ({ items, stockLevels, stats, formulas, addToast }) => {
    const [isItemsModalOpen, setIsItemsModalOpen] = useState(false);
    const [isLowStockModalOpen, setIsLowStockModalOpen] = useState(false);
    const [isInventoryValueModalOpen, setIsInventoryValueModalOpen] = useState(false);
    const [isForecastModalOpen, setIsForecastModalOpen] = useState(false);
    const [forecastData, setForecastData] = useState<BatchForecastResult | null>(null);

    const [aiInsights, setAiInsights] = useState<string>('');
    const [isGeneratingInsights, setIsGeneratingInsights] = useState(false);

    const valueChartRef = useRef<HTMLCanvasElement>(null);
    const opsChartRef = useRef<HTMLCanvasElement>(null);
    const valueChartInstance = useRef<any>(null);
    const opsChartInstance = useRef<any>(null);

    const ai = useMemo(() => new GoogleGenAI({ apiKey: getApiKey() }), []);

    // --- FORECAST STATE LIFTED FROM BATCH CALCULATOR ---
    const [selectedFormulaId, setSelectedFormulaId] = useState<string>(formulas[0]?.id || '');
    const itemMap = useMemo(() => new Map(items.map(item => [item.id, item])), [items]);

    const calculationResult = useMemo<BatchForecastResult | null>(() => {
        if (!selectedFormulaId) return null;
        const formula = formulas.find(f => f.id === selectedFormulaId);
        if (!formula) return null;

        let maxBatches = Infinity;
        let limitingIngredientId: string | null = null;

        const ingredientDetails = formula.ingredients.map(ingredient => {
            const item = itemMap.get(ingredient.itemId);
            const requiredQty = ingredient.quantity;
            const availableStock = stockLevels[ingredient.itemId] ?? 0;
            const possibleBatches = requiredQty > 0 ? Math.floor(availableStock / requiredQty) : Infinity;

            if (possibleBatches < maxBatches) {
                maxBatches = possibleBatches;
                limitingIngredientId = ingredient.itemId;
            }

            return {
                itemId: ingredient.itemId,
                name: item?.name || 'Unknown Item',
                uom: item?.uom || '',
                requiredQty,
                availableStock,
                possibleBatches,
            };
        });

        if (maxBatches === Infinity) {
             maxBatches = 0; // case where formula has no ingredients or all reqs are 0
        }

        return {
            maxBatches,
            limitingIngredientId,
            ingredientDetails,
            formula,
        };
    }, [selectedFormulaId, formulas, stockLevels, itemMap]);
    // ---------------------------------------------------

    const handleGenerateInsights = async () => {
        setIsGeneratingInsights(true);
        setAiInsights('');

        const simplifiedLowStock = stats.lowStockItems.map(({ name, sku, currentStock, reorderPoint, uom }) => 
            ({ name, sku, currentStock, reorderPoint, uom })
        );

        const dataForAI = {
            total_items: stats.totalItems,
            low_stock_items_count: simplifiedLowStock.length,
            low_stock_items_details: simplifiedLowStock,
            total_inventory_value_inr: stats.totalInventoryValue,
            last_6_months_operations: stats.monthlyOperations,
        };

        const prompt = `
You are an expert supply chain and inventory management analyst for a small manufacturing business.
Analyze the following JSON data from their ERP system and provide 3-5 concise, actionable insights in Markdown format.
Focus on identifying potential risks (like stockouts), opportunities for cost savings (like overstocked items), and clear next steps.
Be direct and use simple language. Use bullet points for the insights.

**Data:**
${JSON.stringify(dataForAI, null, 2)}
`;

        try {
            const response = await ai.models.generateContent({
              model: 'gemini-2.5-flash',
              contents: prompt,
            });
            setAiInsights(response.text);
        } catch (error) {
            console.error("AI insight generation failed:", error);
            addToast("Failed to generate AI insights. Please try again.", "error");
            setAiInsights('**Error:** Could not generate insights. The AI service may be temporarily unavailable.');
        } finally {
            setIsGeneratingInsights(false);
        }
    };

    useEffect(() => {
        if (typeof Chart === 'undefined') return;

        const isDarkMode = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
        const gridColor = isDarkMode ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)';
        const textColor = isDarkMode ? '#E5E7EB' : '#374151';

        // Inventory Value Distribution Chart
        if (valueChartRef.current && stats.inventoryValueDistribution.length > 0) {
            if(valueChartInstance.current) valueChartInstance.current.destroy();
            const top5 = stats.inventoryValueDistribution.slice(0, 5);
            const othersValue = stats.inventoryValueDistribution.slice(5).reduce((acc, item) => acc + item.value, 0);
            const labels = [...top5.map(item => item.name), ...(othersValue > 0 ? ['Others'] : [])];
            const data = [...top5.map(item => item.value), ...(othersValue > 0 ? [othersValue] : [])];

            const ctx = valueChartRef.current.getContext('2d');
            if (ctx) {
                valueChartInstance.current = new Chart(ctx, {
                    type: 'pie',
                    data: {
                        labels: labels,
                        datasets: [{
                            label: 'Inventory Value',
                            data: data,
                            backgroundColor: ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6', '#6B7280'],
                            borderColor: isDarkMode ? '#1F2937' : '#FFFFFF',
                            borderWidth: 2,
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { legend: { position: 'right', labels: { color: textColor } }, title: { display: false } }
                    }
                });
            }
        }

        // Monthly Operations Chart
        if (opsChartRef.current && Object.keys(stats.monthlyOperations).length > 0) {
            if(opsChartInstance.current) opsChartInstance.current.destroy();
            const labels = Object.keys(stats.monthlyOperations).map(key => new Date(key + '-02').toLocaleString('default', { month: 'short' }));
            const inflowData = Object.values(stats.monthlyOperations).map((d: any) => d.inflow);
            const consumptionData = Object.values(stats.monthlyOperations).map((d: any) => d.consumption);

            const ctx = opsChartRef.current.getContext('2d');
            if (ctx) {
                opsChartInstance.current = new Chart(ctx, {
                    type: 'bar',
                    data: {
                        labels,
                        datasets: [
                            { label: 'Inflow Value', data: inflowData, backgroundColor: '#3B82F6' },
                            { label: 'Consumption Value', data: consumptionData, backgroundColor: '#F59E0B' }
                        ]
                    },
                    options: {
                        responsive: true, maintainAspectRatio: false,
                        scales: {
                            y: { ticks: { color: textColor }, grid: { color: gridColor } },
                            x: { ticks: { color: textColor }, grid: { color: gridColor } }
                        },
                        plugins: { legend: { position: 'top', labels: { color: textColor } }, title: { display: false } }
                    }
                });
            }
        }

        return () => {
            if(valueChartInstance.current) valueChartInstance.current.destroy();
            if(opsChartInstance.current) opsChartInstance.current.destroy();
        };

    }, [stats]);

    const handleForecastClick = (result: BatchForecastResult) => {
        setForecastData(result);
        setIsForecastModalOpen(true);
    };

    return (
        <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-6">Dashboard</h1>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                 <button 
                    onClick={() => setIsItemsModalOpen(true)}
                    className="text-left focus:outline-none focus:ring-2 rounded-lg shadow-md transition-transform focus:ring-blue-500 hover:scale-105"
                    aria-label="View all items"
                 >
                    <Card className="h-full">
                        <h2 className="text-lg font-semibold text-gray-500 dark:text-gray-400">Total Items</h2>
                        <p className="text-3xl font-bold text-gray-900 dark:text-white mt-2">{stats.totalItems}</p>
                    </Card>
                </button>
                <button
                    onClick={() => setIsInventoryValueModalOpen(true)}
                    className="text-left focus:outline-none focus:ring-2 rounded-lg shadow-md transition-transform focus:ring-green-500 hover:scale-105"
                    aria-label="View inventory value breakdown"
                 >
                     <Card className="h-full">
                        <h2 className="text-lg font-semibold text-gray-500 dark:text-gray-400">Total Inventory Value</h2>
                        <p className="text-3xl font-bold text-green-600 mt-2">
                            {stats.totalInventoryValue.toLocaleString('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 })}
                        </p>
                    </Card>
                </button>
                 <button
                    onClick={() => calculationResult && handleForecastClick(calculationResult)}
                    disabled={!calculationResult}
                    className="text-left focus:outline-none focus:ring-2 rounded-lg shadow-md transition-transform focus:ring-indigo-500 hover:scale-105 disabled:cursor-default disabled:hover:scale-100 disabled:opacity-70"
                    aria-label="View production forecast"
                 >
                    <Card className="h-full">
                        <h2 className="text-lg font-semibold text-gray-500 dark:text-gray-400">Max Possible Batches</h2>
                        <p className="text-3xl font-bold text-indigo-600 dark:text-indigo-400 mt-2">{calculationResult?.maxBatches ?? 'N/A'}</p>
                    </Card>
                </button>
                <button 
                    onClick={() => setIsLowStockModalOpen(true)}
                    className={`text-left focus:outline-none focus:ring-2 rounded-lg shadow-md transition-transform ${stats.lowStockItems.length > 0 ? 'focus:ring-orange-500 hover:scale-105' : 'cursor-default'}`}
                    aria-label="View low stock items"
                    disabled={stats.lowStockItems.length === 0}
                 >
                    <Card className="h-full">
                        <h2 className="text-lg font-semibold text-gray-500 dark:text-gray-400">Items Low on Stock</h2>
                        <p className={`text-3xl font-bold mt-2 ${stats.lowStockItems.length > 0 ? 'text-orange-500' : 'text-gray-900 dark:text-white'}`}>
                            {stats.lowStockItems.length}
                        </p>
                    </Card>
                </button>
            </div>

            <div className="mt-8">
                <BatchCalculator 
                    formulas={formulas}
                    selectedFormulaId={selectedFormulaId}
                    onFormulaChange={setSelectedFormulaId}
                    calculationResult={calculationResult}
                    onForecastClick={handleForecastClick}
                />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-5 gap-6 mt-8">
                <Card className="lg:col-span-2 h-96">
                    <h2 className="text-xl font-semibold mb-4">Inventory Value Distribution</h2>
                    <div className="h-72"><canvas ref={valueChartRef}></canvas></div>
                </Card>
                 <Card className="lg:col-span-3 h-96">
                     <h2 className="text-xl font-semibold mb-4">Monthly Inflow vs. Consumption (Value)</h2>
                     <div className="h-72"><canvas ref={opsChartRef}></canvas></div>
                </Card>
            </div>

             <div className="mt-8">
                <Card>
                     <div className="flex items-center mb-4">
                        <SparklesIcon className="w-6 h-6 mr-3 text-purple-500"/>
                        <h2 className="text-xl font-semibold">AI-Powered Insights</h2>
                    </div>
                    {isGeneratingInsights ? (
                        <div className="flex items-center justify-center h-48">
                            <SpinnerIcon className="w-8 h-8 animate-spin text-purple-500" />
                            <p className="ml-4 text-gray-500 dark:text-gray-400">Analyzing your data...</p>
                        </div>
                    ) : aiInsights ? (
                        <div>
                            <MarkdownRenderer content={aiInsights} />
                            <button
                                onClick={handleGenerateInsights}
                                className="mt-4 text-sm font-semibold text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                            >
                                Regenerate Insights
                            </button>
                        </div>
                    ) : (
                        <div className="text-center h-48 flex flex-col justify-center items-center">
                            <p className="text-gray-500 dark:text-gray-400 mb-4">Get actionable advice on your inventory by asking our AI analyst.</p>
                            <button 
                                onClick={handleGenerateInsights}
                                className="bg-purple-600 text-white px-5 py-2 rounded-md text-sm font-semibold hover:bg-purple-700 shadow focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-purple-500 flex items-center gap-2"
                            >
                                <SparklesIcon className="w-4 h-4"/>
                                Generate Actionable Insights
                            </button>
                        </div>
                    )}
                </Card>
            </div>

             <div className="mt-8">
                <Card>
                    <div className="flex items-center mb-4">
                        <WarningIcon className="w-6 h-6 mr-3 text-orange-500"/>
                        <h2 className="text-xl font-semibold">Low Stock Alerts</h2>
                    </div>
                    {stats.lowStockItems.length > 0 ? (
