import React, { useState, useEffect, useRef } from 'react';
import type { Item, ToastMessage } from '../types';

interface CreateItemModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (item: Omit<Item, 'id' | 'createdAt'>) => void;
  addToast: (message: string, type: ToastMessage['type']) => void;
}

const CreateItemModal: React.FC<CreateItemModalProps> = ({ isOpen, onClose, onAdd, addToast }) => {

  const getInitialState = () => ({
    sku: '',
    name: '',
    uom: '',
    reorderPoint: '0',
    costPrice: '',
  });

  const [formData, setFormData] = useState(getInitialState());

  const modalRef = useRef<HTMLDivElement>(null);
  const firstInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
        setFormData(getInitialState());
        setTimeout(() => firstInputRef.current?.focus(), 100);
    }
  }, [isOpen]);

  useEffect(() => {
    const handleEsc = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
    };
    if (isOpen) window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const reorderPoint = parseFloat(formData.reorderPoint);
    const costPrice = parseFloat(formData.costPrice);

    if (!formData.sku || !formData.name || !formData.uom || isNaN(reorderPoint)) {
      addToast('Please fill in SKU, Name, UOM, and a valid Reorder Point.', 'error');
      return;
    }

    onAdd({
        ...formData,
        reorderPoint,
        costPrice: isNaN(costPrice) ? undefined : costPrice,
    });
    onClose();
  };

  const inputStyles = "mt-1 block w-full px-3 py-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm placeholder-gray-400 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm";

  return (
    <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose} role="dialog" aria-modal="true" aria-labelledby="modal-title">
      <div ref={modalRef} className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-lg" onClick={e => e.stopPropagation()}>
        <h2 id="modal-title" className="text-xl font-bold mb-4 text-gray-900 dark:text-white">Add New Raw Material</h2>
        <form onSubmit={handleSubmit} noValidate>
            <div className="space-y-4">
                <div>
                    <label htmlFor="sku" className="block text-sm font-medium text-gray-700 dark:text-gray-300">SKU</label>
                    <input ref={firstInputRef} type="text" id="sku" name="sku" value={formData.sku} onChange={handleChange} className={inputStyles} required/>
                </div>
                 <div>
                    <label htmlFor="name" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Name</label>
                    <input type="text" id="name" name="name" value={formData.name} onChange={handleChange} className={inputStyles} required />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label htmlFor="uom" className="block text-sm font-medium text-gray-700 dark:text-gray-300">UOM</label>
                        <input type="text" id="uom" name="uom" value={formData.uom} onChange={handleChange} className={inputStyles} required />
                    </div>
                    <div>
                        <label htmlFor="reorderPoint" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Reorder Point</label>
                        <input type="number" id="reorderPoint" name="reorderPoint" value={formData.reorderPoint} onChange={handleChange} className={inputStyles} required min="0"/>
                    </div>
                </div>
                <div>
                    <label htmlFor="costPrice" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Cost Price</label>
                    <input type="number" id="costPrice" name="costPrice" value={formData.costPrice} onChange={handleChange} className={inputStyles} min="0" step="0.01"/>
                </div>
            </div>
            <div className="mt-6 flex justify-end space-x-3">
                <button type="button" onClick={onClose} className="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-300 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-500 rounded-md shadow-sm hover:bg-gray-50 dark:hover:bg-gray-600">Cancel</button>
                <button type="submit" className="px-4 py-2 text-sm font-medium text-white bg-blue-600 border border-transparent rounded-md shadow-sm hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500">Add Item</button>
            </div>
        </form>
      </div>
    </div>
  );
};
export default CreateItemModal;
