                </div>

                <div className="mb-6 border-b border-gray-200 dark:border-gray-700 no-print">
                    <nav className="-mb-px flex space-x-6 overflow-x-auto" aria-label="Tabs">
                        {tabs.map(tab => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`${
                                    activeTab === tab.id
                                        ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                                        : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300 dark:text-gray-400 dark:hover:text-gray-200 dark:hover:border-gray-500'
                                } whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm focus:outline-none`}
                            >
                                {tab.label}
                            </button>
                        ))}
                    </nav>
                </div>

                <div>
                    <div id="current-stock-view" style={{ display: activeTab === 'current' ? 'block' : 'none' }}>
                        <CurrentStockView 
                            items={items} 
                            stockLevels={stockLevels} 
                            inflowTransactions={transactions}
                            deleteItem={deleteItem} 
                            onEditItem={setEditingItem} 
                        />
                    </div>
                    <div id="movement-stock-view" style={{ display: activeTab === 'movement' ? 'block' : 'none' }}><StockMovementTable items={items} inflow={transactions} consumption={consumptionTransactions} /></div>
                </div>
            </div>
            {editingItem && (
                <EditItemModal
                    isOpen={!!editingItem}
                    onClose={() => setEditingItem(null)}
                    item={editingItem}
                    onUpdate={updateItem}
                />
            )}
        </>
    );
};

interface CurrentStockViewProps {
    items: Item[];
    stockLevels: Record<string, number>;
    inflowTransactions: InflowTransaction[];
    deleteItem: (itemId: string) => void;
    onEditItem: (item: Item) => void;
}

const CurrentStockView: React.FC<CurrentStockViewProps> = ({ items, stockLevels, inflowTransactions, deleteItem, onEditItem }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [showLowStockOnly, setShowLowStockOnly] = useState(false);

    const combinedItemData = useMemo(() => {
        return items.map(item => {
            // Calculate Total Inflow: Sum of all quantities for this item in inflow transactions
            const totalInflow = inflowTransactions
                .filter(t => t.itemId === item.id)
                .reduce((sum, t) => sum + t.quantity, 0);

            return {
                ...item,
                currentStock: stockLevels[item.id] ?? 0,
                totalInflow: totalInflow
            };
        }).sort((a, b) => a.name.localeCompare(b.name));
    }, [items, stockLevels, inflowTransactions]);

    const filteredItems = useMemo(() => {
        let filtered = combinedItemData;

        if (showLowStockOnly) {
            filtered = filtered.filter(item => item.currentStock < item.reorderPoint);
        }

        if (!searchTerm) return filtered;
        const lowercasedFilter = searchTerm.toLowerCase();
        return filtered.filter(item =>
            item.name.toLowerCase().includes(lowercasedFilter) ||
            item.sku.toLowerCase().includes(lowercasedFilter)
        );
    }, [combinedItemData, searchTerm, showLowStockOnly]);

    return (
        <div>
             <div className="flex justify-end mb-4 no-print items-center gap-4">
                 <div className="flex items-center">
                    <input
                        type="checkbox"
                        id="lowStockToggle"
                        checked={showLowStockOnly}
                        onChange={e => setShowLowStockOnly(e.target.checked)}
                        className="h-4 w-4 rounded border-gray-300 dark:border-gray-600 text-blue-600 focus:ring-blue-500 bg-white dark:bg-gray-700"
                    />
                    <label htmlFor="lowStockToggle" className="ml-2 block text-sm text-gray-900 dark:text-gray-300 select-none">
                        Show Low Stock Only
                    </label>
                </div>
                <div className="relative">
                    <input
                        type="text"
                        placeholder="Search by name or SKU..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-10 pr-4 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md focus:ring-blue-500 focus:border-blue-500 w-64"
                        aria-label="Search items"
                    />
                    <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                </div>
            </div>
            <StockTable items={filteredItems} deleteItem={deleteItem} onEditItem={onEditItem} />
        </div>
    )
}

export default Stock;
