                                </ul>
                            </div>
                        )}
                    </>
                )}

                <div>
                    <label htmlFor="con-txnDate" className="block text-sm font-medium">Consumption Date</label>
                    <input type="date" id="con-txnDate" value={txnDate} onChange={e => setTxnDate(e.target.value)} className={inputStyles} required/>
