import React, { useState, useEffect, useMemo } from 'react';
import type { Item } from '../types';
import { SearchIcon } from './Icon';

interface InventoryValueModalProps {
  isOpen: boolean;
  onClose: () => void;
  items: Item[];
  stockLevels: Record<string, number>;
}

const InventoryValueModal: React.FC<InventoryValueModalProps> = ({ isOpen, onClose, items, stockLevels }) => {
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (!isOpen) {
      setSearchTerm('');
    }
  }, [isOpen]);

  useEffect(() => {
    const handleEsc = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };
    if (isOpen) {
      window.addEventListener('keydown', handleEsc);
    }
    return () => {
      window.removeEventListener('keydown', handleEsc);
    };
  }, [isOpen, onClose]);

  const inventoryValueData = useMemo(() => {
    return items.map(item => {
        const currentStock = stockLevels[item.id] ?? 0;
        const costPrice = item.costPrice ?? 0;
        return {
            ...item,
            currentStock,
            totalValue: currentStock * costPrice
        }
    }).sort((a,b) => b.totalValue - a.totalValue);
  }, [items, stockLevels]);

  const filteredData = useMemo(() => {
    if (!searchTerm) return inventoryValueData;
    return inventoryValueData.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      item.sku.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [inventoryValueData, searchTerm]);

  const grandTotal = useMemo(() => {
