// --- Helper Components defined OUTSIDE the main component to prevent re-creation and focus loss ---
// This is the critical fix for the "single character entry" bug.
const TempInput: React.FC<{ group: keyof ProcessLogSheetData, param: string, label: string, data: ProcessLogSheetData, onChange: (g: any, p: any, t: any, v: any) => void, focusInput: (id: string) => void, inputRefs: React.MutableRefObject<Record<string, HTMLInputElement | HTMLTextAreaElement>> }> = ({ group, param, label, data, onChange, focusInput, inputRefs }) => (
    <tr className="border-b dark:border-gray-700">
        <td className="px-2 py-1 font-semibold cursor-pointer hover:text-blue-500" onClick={() => focusInput(`log-${group}-${param}-act`)}>{label}</td>
        <td className="p-1">
            <input 
                id={`log-${group}-${param}-act`} 
                key={`log-${group}-${param}-act`} // Add key for stable input instance
                ref={el => (inputRefs.current[`log-${group}-${param}-act`] = el!)}
                type="text" 
                value={(data as any)[group]?.[param]?.act || ''} 
                onChange={(e) => onChange(group, param, 'act', e.target.value)} 
                className="w-full bg-gray-50 dark:bg-gray-700 text-center text-sm p-1 rounded border dark:border-gray-600" 
            />
        </td>
        <td className="p-1">
            <input 
                id={`log-${group}-${param}-set`} 
                key={`log-${group}-${param}-set`} // Add key for stable input instance
                ref={el => (inputRefs.current[`log-${group}-${param}-set`] = el!)}
                type="text" 
                value={(data as any)[group]?.[param]?.set || ''} 
                onChange={(e) => onChange(group, param, 'set', e.target.value)} 
                className="w-full bg-gray-50 dark:bg-gray-700 text-center text-sm p-1 rounded border dark:border-gray-600" 
            />
        </td>
    </tr>
);

const ParamInput: React.FC<{ group?: keyof ProcessLogSheetData, param: string, label: string, sNo: string, data: ProcessLogSheetData, onChange: (g: any, p: any, v: any) => void, onHeaderChange: (e:any) => void, focusInput: (id: string) => void, inputRefs: React.MutableRefObject<Record<string, HTMLInputElement | HTMLTextAreaElement>> }> = ({ group, param, label, sNo, data, onChange, onHeaderChange, focusInput, inputRefs }) => (
    <tr className="border-b dark:border-gray-700">
        <td className="px-2 py-1 text-center font-semibold">{sNo}</td>
        <td className="px-2 py-1 font-semibold cursor-pointer hover:text-blue-500" onClick={() => focusInput(`log-${group || ''}-${param}`)}>{label}</td>
        <td className="p-1" colSpan={2}>
            <input 
                id={`log-${group || ''}-${param}`} 
                key={`log-${group || ''}-${param}`} // Add key for stable input instance
                ref={el => (inputRefs.current[`log-${group || ''}-${param}`] = el!)}
                type="text" 
                value={group ? (data as any)[group]?.[param] || '' : (data as any)[param] || ''} 
                onChange={(e) => group ? onChange(group, param, e.target.value) : onHeaderChange({ target: { name: param, value: e.target.value } } as any)} 
                className="w-full bg-gray-50 dark:bg-gray-700 text-sm p-1 rounded border dark:border-gray-600" 
            />
        </td>
    </tr>
);

interface ProcessLogSheetModalProps {
    isOpen: boolean;
    onClose: () => void;
    die: Die | null;
    onSave: (die: Die) => void;
    addToast: (message: string, type: ToastMessage['type']) => void;
}

const ProcessLogSheetModal: React.FC<ProcessLogSheetModalProps> = ({ isOpen, onClose, die, onSave, addToast }) => {
    // IMPORTANT: Use deep copy to initialize state to prevent mutation of original die object before saving
    const [formData, setFormData] = useState<ProcessLogSheetData>({});
    const inputRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement>>({});

    const modalRef = useRef<HTMLDivElement>(null);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const startPos = useRef({ x: 0, y: 0 });

    useEffect(() => {
        if (isOpen && die) {
            setFormData(die.processLog || {});
            setPosition({ x: 0, y: 0 }); // Reset position on open
        }
    }, [isOpen, die]);

    useEffect(() => {
        const handleEsc = (event: KeyboardEvent) => {
            if (event.key === 'Escape') onClose();
        };
        if (isOpen) window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [isOpen, onClose]);

    const handleMouseDownHeader = (e: React.MouseEvent) => {
        if (e.button !== 0) return;
        setIsDragging(true);
        dragStart.current = { x: e.clientX, y: e.clientY };
        startPos.current = { ...position };
    };

    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => {
            if (isDragging) {
                e.preventDefault();
                setPosition({ x: startPos.current.x + (e.clientX - dragStart.current.x), y: startPos.current.y + (e.clientY - dragStart.current.y) });
            }
        };
        const onMouseUp = () => setIsDragging(false);
        if (isDragging) {
            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        }
        return () => {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
        };
    }, [isDragging]);

    if (!isOpen || !die) return null;

    const handleTempParamChange = (group: keyof ProcessLogSheetData, param: string, type: 'act' | 'set', value: string) => {
        setFormData(prev => ({
            ...prev,
            [group]: {
                ...(prev[group] || {}),
                [param]: {
                    ...((prev[group] as any)?.[param] || {}), // Cast to any to access dynamic property
                    [type]: value
                }
            }
        }));
    };

    const handleParamChange = (group: keyof ProcessLogSheetData, param: string, value: string) => {
        setFormData(prev => ({
            ...prev,
            [group]: {
                ...(prev[group] || {}),
                [param]: value
            }
        }));
    };

    // For direct header fields (not grouped)
    const handleHeaderChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const focusInput = useCallback((id: string) => {
        inputRefs.current[id]?.focus();
    }, []);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave({ ...die, processLog: formData });
        addToast('Process Log Saved!', 'success');
        onClose();
    };

    const inputStyle = "w-full bg-gray-50 dark:bg-gray-700 text-sm p-1 rounded border dark:border-gray-600 focus:outline-none focus:ring-1 focus:ring-blue-500";
    const modalStyle = { transform: `translate(${position.x}px, ${position.y}px)` };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[90] flex justify-center items-center p-4" onMouseDown={onClose}>
            <div ref={modalRef} style={modalStyle} className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-4xl flex flex-col max-h-[90vh] border border-gray-200 dark:border-gray-600 my-auto" onMouseDown={e => e.stopPropagation()}>
                <div onMouseDown={handleMouseDownHeader} className="bg-gray-900 text-white px-6 py-4 rounded-t-xl cursor-move flex justify-between items-center shrink-0 select-none z-10 relative min-h-[64px]">
                    <h2 className="text-xl font-bold flex items-center gap-2">Process Log Sheet: {die.dieNo}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white text-2xl font-bold">&times;</button>
                </div>
                <div className="p-6 overflow-y-auto flex-1 min-h-0 bg-white dark:bg-gray-800">
                    <form onSubmit={handleSubmit} className="space-y-6">
                        {/* Header Info */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div><label className="block text-xs font-medium mb-1">Date</label><input type="date" name="date" value={formData.date || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Machine No.</label><input type="text" name="machineNo" value={formData.machineNo || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Tool ID</label><input type="text" name="toolId" value={formData.toolId || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Tool Man</label><input type="text" name="toolMan" value={formData.toolMan || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Profile Speed</label><input type="text" name="profileSpeed" value={formData.profileSpeed || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Output Per Hour</label><input type="text" name="outputPerHour" value={formData.outputPerHour || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Profile Colour</label><input type="text" name="profileColour" value={formData.profileColour || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                        </div>

                        {/* Temperatures */}
                        <div className="border rounded-md dark:border-gray-700">
                            <table className="w-full text-sm">
                                <thead>
                                    <tr className="bg-gray-100 dark:bg-gray-700"><th className="px-2 py-1 text-left font-semibold" colSpan={1}>Barrel/Tooling Temp</th><th className="px-2 py-1 text-center font-semibold">ACT</th><th className="px-2 py-1 text-center font-semibold">SET</th></tr>
                                </thead>
                                <tbody>
                                    <tr className="bg-gray-50 dark:bg-gray-700/50"><td colSpan={3} className="px-2 py-1 font-semibold">Barrel Zones</td></tr>
                                    <TempInput group="barrelTemp" param="bz1" label="BZ-1" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz2" label="BZ-2" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz3" label="BZ-3" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz4" label="BZ-4" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz5" label="BZ-5" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="bz6" label="BZ-6" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="ch1" label="CH-1" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="barrelTemp" param="ch2" label="CH-2" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <tr className="bg-gray-50 dark:bg-gray-700/50"><td colSpan={3} className="px-2 py-1 font-semibold">Tooling Zones</td></tr>
                                    <TempInput group="toolingTemp" param="dz1" label="DZ-1" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="toolingTemp" param="dz2" label="DZ-2" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="toolingTemp" param="dz3" label="DZ-3" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <TempInput group="toolingTemp" param="dz4" label="DZ-4" data={formData} onChange={handleTempParamChange} focusInput={focusInput} inputRefs={inputRefs} />
                                </tbody>
                            </table>
                        </div>

                        {/* Other Parameters */}
                        <div className="border rounded-md dark:border-gray-700">
                            <table className="w-full text-sm">
                                <thead>
                                    <tr className="bg-gray-100 dark:bg-gray-700"><th className="px-2 py-1 text-center font-semibold" colSpan={2}>S.No.</th><th className="px-2 py-1 text-left font-semibold" colSpan={2}>Parameters</th></tr>
                                </thead>
                                <tbody>
                                    <ParamInput sNo="1" param="extruderRpm" label="Extruder RPM" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="2" param="screwTorque" label="Screw Torque" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="3" param="feederBlend" label="Feeder Blend" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="4" param="haulOffRpm" label="Haul Off RPM" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="5" param="meltTemp" label="Melt Temp" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="6" param="meltPressure" label="Melt Pressure" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="7" param="degasing" label="Degasing" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />

                                    <tr className="bg-gray-50 dark:bg-gray-700/50"><td colSpan={4} className="px-2 py-1 font-semibold">Calibrator</td></tr>
                                    <ParamInput sNo="8" group="calibrator" param="vacuum1" label="Vacuum 1" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="9" group="calibrator" param="vacuum2" label="Vacuum 2" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="10" group="calibrator" param="vacuum3" label="Vacuum 3" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="11" group="calibrator" param="vacuum4" label="Vacuum 4" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="12" group="calibrator" param="vacuum5" label="Vacuum 5" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="13" group="calibrator" param="waterTemp" label="Water Temp" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="14" group="calibrator" param="waterPressure" label="Water Pressure" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />

                                    <tr className="bg-gray-50 dark:bg-gray-700/50"><td colSpan={4} className="px-2 py-1 font-semibold">Cooling Tank</td></tr>
                                    <ParamInput sNo="15" group="coolingTank" param="vacuumLR1" label="Vacuum LR 1" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="16" group="coolingTank" param="vacuumLR2" label="Vacuum LR 2" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="17" group="coolingTank" param="vacuumLR3" label="Vacuum LR 3" data={formData} onChange={handleParamChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />

                                    <ParamInput sNo="18" param="haulOffPressure" label="Haul Off Pressure" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="19" param="counter" label="Counter" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="20" param="cutterClamping" label="Cutter Clamping" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                    <ParamInput sNo="21" param="timeOfTripping" label="Time of Tripping" data={formData} onChange={handleHeaderChange} onHeaderChange={handleHeaderChange} focusInput={focusInput} inputRefs={inputRefs} />
                                </tbody>
                            </table>
                        </div>

                        {/* Signatures & Remarks */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div><label className="block text-xs font-medium mb-1">Signature Operator</label><input type="text" name="signatureOperator" value={formData.signatureOperator || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                            <div><label className="block text-xs font-medium mb-1">Signature Engineer</label><input type="text" name="signatureEngineer" value={formData.signatureEngineer || ''} onChange={handleHeaderChange} className={inputStyle} /></div>
                        </div>
                        <div><label className="block text-xs font-medium mb-1">Remarks</label><textarea name="remarks" rows={3} value={formData.remarks || ''} onChange={handleHeaderChange} className={inputStyle}></textarea></div>
                    </form>
                </div>
                <div className="p-4 bg-gray-100 dark:bg-gray-700 rounded-b-xl flex justify-end gap-3 shrink-0 border-t border-gray-200 dark:border-gray-600">
                    <button type="button" onClick={onClose} className="px-5 py-2 bg-white dark:bg-gray-600 border rounded-md hover:bg-gray-50 dark:hover:bg-gray-500 text-gray-700 dark:text-white transition-colors">Cancel</button>
                    <button type="submit" onClick={handleSubmit} className="px-6 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 shadow transition-colors">Save Log</button>
                </div>
            </div>
        </div>
    );
};


const DiesAndPlanning: React.FC<DiesAndPlanningProps> = (props) => {
    const { dies, productionPlans, profiles, addToast, addDie, updateDie, deleteDie, addProductionPlan, updateProductionPlan, deleteProductionPlan, brands, addBrand, updateBrand, deleteBrand, addProfile } = props;
    const [activeTab, setActiveTab] = useState<Tab>('dies');
    const [searchTerm, setSearchTerm] = useState('');
    const [brandFilter, setBrandFilter] = useState('All');

    const [isDieModalOpen, setIsDieModalOpen] = useState(false);
    const [editingDie, setEditingDie] = useState<Die | null>(null);

    const [isPlanModalOpen, setIsPlanModalOpen] = useState(false);
    const [editingPlan, setEditingPlan] = useState<ProductionPlan | null>(null);

    const [logSheetDie, setLogSheetDie] = useState<Die | null>(null);
    const [isManageBrandsModalOpen, setIsManageBrandsModalOpen] = useState(false);
    const [isAddProfileSubModalOpen, setIsAddProfileSubModalOpen] = useState(false); // State for AddProfileModal in DieModal

    const [newlyCreatedProfileId, setNewlyCreatedProfileId] = useState<string | null>(null); // For AddProfileModal interaction


    const filteredDies = useMemo(() => {
        let filtered = dies;
        if (brandFilter !== 'All') {
            filtered = filtered.filter(d => d.brand === brandFilter);
        }
        if (!searchTerm) return filtered;
        const lowerSearch = searchTerm.toLowerCase();
        return filtered.filter(d => d.dieNo.toLowerCase().includes(lowerSearch));
    }, [dies, searchTerm, brandFilter]);

    const filteredPlans = useMemo(() => {
        if (!searchTerm) return productionPlans;
        const lowerSearch = searchTerm.toLowerCase();
        return productionPlans.filter(p => p.machineNo.toLowerCase().includes(lowerSearch));
    }, [productionPlans, searchTerm]);

    const dieMap = useMemo(() => new Map(dies.map(d => [d.id, d.dieNo])), [dies]);
    const profileMap = useMemo(() => new Map(profiles.map(p => [p.id, p])), [profiles]);

    const tabs: { id: Tab; label: string }[] = [
        { id: 'dies', label: 'Dies Parameter' },
        { id: 'planning', label: 'Production Plan' },
    ];

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Dies & Planning</h1>
                <div>
                    {activeTab === 'dies' && <button onClick={() => setIsDieModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 shadow">+ Add Die</button>}
                    {activeTab === 'planning' && <button onClick={() => setIsPlanModalOpen(true)} className="bg-green-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-green-700 shadow">+ Add Plan</button>}
                </div>
            </div>

            <div className="mb-6 border-b border-gray-200 dark:border-gray-700 flex justify-between items-end">
                <nav className="-mb-px flex space-x-6 overflow-x-auto">
                    {tabs.map(tab => <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`${activeTab === tab.id ? 'border-blue-500 text-blue-600 dark:text-blue-400' : 'border-transparent text-gray-500 dark:text-gray-400'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm focus:outline-none`}>{tab.label}</button>)}
                </nav>
                <div className="flex items-center gap-4">
                     {activeTab === 'dies' && (
                        <div className="flex bg-gray-200 dark:bg-gray-700 rounded-lg p-1 items-center">
                            <button onClick={() => setBrandFilter('All')} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === 'All' ? 'bg-white dark:bg-gray-600 shadow' : 'text-gray-500 dark:text-gray-400'}`}>All</button>
                            {brands.map(brand => <button key={brand} onClick={() => setBrandFilter(brand)} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${brandFilter === brand ? 'bg-white dark:bg-gray-600 shadow' : 'text-gray-500 dark:text-gray-400'}`}>{brand}</button>)}
                            <button onClick={() => setIsManageBrandsModalOpen(true)} className="ml-1 px-2 py-1 text-gray-500" title="Manage Brands"><PencilIcon className="w-3 h-3" /></button>
                        </div>
                    )}
                    <div className="mb-2 relative hidden sm:block"><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="pl-8 pr-4 py-1 text-sm border border-gray-300 dark:border-gray-600 dark:bg-gray-700 rounded-md w-64" /><SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" /></div>
                </div>
            </div>

            {activeTab === 'dies' && (
                <div className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                    <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                            <tr>
                                <th className="px-6 py-3">Brand</th><th className="px-6 py-3">Die No.</th><th className="px-6 py-3">Profile</th><th className="px-6 py-3">Cavities</th><th className="px-6 py-3">Output (Kg/Hr)</th><th className="px-6 py-3">Lifespan (m)</th><th className="px-6 py-3">Status</th><th className="px-6 py-3 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredDies.map(die => (
                                <tr key={die.id} className="border-b dark:border-gray-700">
                                    <td className="px-6 py-4"><span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300">{die.brand || '-'}</span></td>
                                    <td className="px-6 py-4 font-medium">{die.dieNo}</td>
                                    <td className="px-6 py-4">{profileMap.get(die.profileId)?.name || 'N/A'}</td>
                                    <td className="px-6 py-4">{die.cavities}</td>
                                    <td className="px-6 py-4">{die.expectedOutputKgHr}</td>
                                    <td className="px-6 py-4">{die.lifespanMeters.toLocaleString()}</td>
                                    <td className="px-6 py-4">{die.status}</td>
                                    <td className="px-6 py-4 text-right space-x-3">
                                        <button onClick={() => setLogSheetDie(die)} className="text-green-500 hover:underline font-medium">Log Sheet</button>
                                        <button onClick={() => setEditingDie(die)} className="text-blue-500 hover:underline"><PencilIcon className="w-4 h-4 inline"/></button>
                                        <button onClick={() => deleteDie(die.id)} className="text-red-500 hover:underline"><TrashIcon className="w-4 h-4 inline"/></button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {activeTab === 'planning' && (
                <div className="bg-white dark:bg-gray-800 rounded-md shadow overflow-hidden">
                     <table className="w-full text-sm text-left text-gray-600 dark:text-gray-400">
                        <thead className="text-xs text-gray-700 dark:text-gray-300 uppercase bg-gray-50 dark:bg-gray-700">
                            <tr>
                                <th className="px-6 py-3">Date</th><th className="px-6 py-3">Shift</th><th className="px-6 py-3">Machine No.</th><th className="px-6 py-3">Die No.</th><th className="px-6 py-3">Target (m)</th><th className="px-6 py-3 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredPlans.map(plan => (
                                <tr key={plan.id} className="border-b dark:border-gray-700">
                                    <td className="px-6 py-4">{new Date(plan.date  + 'T00:00:00').toLocaleDateString()}</td>
                                    <td className="px-6 py-4">{plan.shift}</td>
                                    <td className="px-6 py-4">{plan.machineNo}</td>
                                    <td className="px-6 py-4">{dieMap.get(plan.dieId) || 'N/A'}</td>
                                    <td className="px-6 py-4">{plan.targetMeters.toLocaleString()}</td>
                                    <td className="px-6 py-4 text-right space-x-3"><button onClick={() => setEditingPlan(plan)} className="text-blue-500 hover:underline"><PencilIcon className="w-4 h-4 inline"/></button><button onClick={() => deleteProductionPlan(plan.id)} className="text-red-500 hover:underline"><TrashIcon className="w-4 h-4 inline"/></button></td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            <Portal>
                <DieModal 
                    isOpen={isDieModalOpen || !!editingDie}
                    onClose={() => { setIsDieModalOpen(false); setEditingDie(null); setNewlyCreatedProfileId(null); }} // Clear newly created ID on close
                    die={editingDie}
                    profiles={profiles}
                    brands={brands}
                    onSave={(data) => {
                        if (editingDie) {
                            updateDie({ ...editingDie, ...data });
                        } else {
                            addDie(data);
                        }
                    }}
                    addToast={addToast}
                    addProfile={addProfile} // Pass addProfile to DieModal
                    isAddProfileSubModalOpen={isAddProfileSubModalOpen} // Pass state
                    setIsAddProfileSubModalOpen={setIsAddProfileSubModalOpen} // Pass setter
                    setNewlyCreatedProfileId={setNewlyCreatedProfileId} // Pass setter
                    newlyCreatedProfileId={newlyCreatedProfileId} // Pass the ID
                />
            </Portal>

             <Portal>
                <ProductionPlanModal 
                    isOpen={isPlanModalOpen || !!editingPlan}
                    onClose={() => { setIsPlanModalOpen(false); setEditingPlan(null); }}
                    plan={editingPlan}
                    dies={dies}
                    onSave={(data) => {
                        if (editingPlan) {
                            updateProductionPlan({ ...editingPlan, ...data });
                        } else {
                            addProductionPlan(data);
                        }
                    }}
                    addToast={addToast}
                />
            </Portal>

            <Portal>
                <ProcessLogSheetModal 
                    isOpen={!!logSheetDie}
                    onClose={() => setLogSheetDie(null)}
                    die={logSheetDie}
                    onSave={updateDie}
                    addToast={addToast}
                />
            </Portal>
            <Portal><ManageBrandsModal isOpen={isManageBrandsModalOpen} onClose={() => setIsManageBrandsModalOpen(false)} brands={brands} addBrand={addBrand} updateBrand={updateBrand} deleteBrand={deleteBrand} addToast={addToast} /></Portal>
        </div>
    );
};

interface DieModalProps {
    isOpen: boolean;
    onClose: () => void;
    die: Die | null;
    profiles: Profile[];
    brands: string[];
    onSave: (data: Omit<Die, 'id' | 'createdAt' | 'brand'> | Die) => void;
    addToast: (message: string, type: ToastMessage['type']) => void;
    addProfile: (profile: Omit<Profile, 'id' | 'createdAt'>) => Profile;
    isAddProfileSubModalOpen: boolean; 
    setIsAddProfileSubModalOpen: (isOpen: boolean) => void; 
    setNewlyCreatedProfileId: (id: string | null) => void; 
    newlyCreatedProfileId: string | null; // Receive the ID
}

const DieModal: React.FC<DieModalProps> = ({ isOpen, onClose, die, profiles, brands, onSave, addToast, addProfile, isAddProfileSubModalOpen, setIsAddProfileSubModalOpen, setNewlyCreatedProfileId, newlyCreatedProfileId }) => {
    const [form, setForm] = useState({ dieNo: '', profileId: '', cavities: 1, expectedOutputKgHr: 100, lifespanMeters: 500000, status: 'ACTIVE' as 'ACTIVE' | 'INACTIVE' | 'MAINTENANCE' });
    const [modalBrandFilter, setModalBrandFilter] = useState('All');

    useEffect(() => {
        if (isOpen) {
            if (die) {
                setForm(die);
                setModalBrandFilter(die.brand || 'All'); // Set filter if editing existing die
            } else {
                setForm({ dieNo: '', profileId: '', cavities: 1, expectedOutputKgHr: 100, lifespanMeters: 500000, status: 'ACTIVE' });
            }
            // Clear newly created ID when opening a fresh modal
            setNewlyCreatedProfileId(null); 
        }
    }, [isOpen, die, setNewlyCreatedProfileId]); // Only depend on props that trigger form reset

    // FIX: This useEffect now correctly handles setting the profileId AFTER sub-modal closes
    useEffect(() => {
        if (!isAddProfileSubModalOpen && newlyCreatedProfileId) {
            setForm(prev => ({ ...prev, profileId: newlyCreatedProfileId }));
            setNewlyCreatedProfileId(null); // Clear it after use in parent
        }
    }, [isAddProfileSubModalOpen, newlyCreatedProfileId, setNewlyCreatedProfileId]);

    const filteredProfiles = useMemo(() => {
        if (modalBrandFilter === 'All') return profiles;
        return profiles.filter((p: any) => p.brand === modalBrandFilter);
    }, [profiles, modalBrandFilter]);

    if (!isOpen) return null;

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if(!form.profileId) {
            addToast('Please select a profile.', 'error');
            return;
        }
        // When saving, the brand is automatically set by the store.addDie/updateDie action
        onSave(form);
        onClose();
    };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none";

    return (
         <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold mb-4 dark:text-white">{die ? 'Edit Die' : 'Add New Die'}</h3>
                <form onSubmit={handleSubmit} className="grid grid-cols-2 gap-4">
                    <input placeholder="Die No." value={form.dieNo} onChange={e => setForm({...form, dieNo: e.target.value})} className={inputClass} required />

                    <div className="col-span-1">
                        <select 
                            value={modalBrandFilter} 
                            onChange={e => setModalBrandFilter(e.target.value)} 
                            className={`${inputClass} mb-1 bg-gray-50 border-b-2 border-blue-200`}
                        >
                            <option value="All">Filter Profile by Brand</option>
                            {brands.map((b:string) => <option key={b} value={b}>{b}</option>)}
                        </select>
                         <select 
                            value={form.profileId} 
                            onChange={e => {
                                if (e.target.value === '__ADD_NEW_PROFILE__') {
                                    setIsAddProfileSubModalOpen(true);
                                } else {
                                    setForm(prev => ({...prev, profileId: e.target.value}));
                                }
                            }} 
                            className={inputClass} 
                            required
                        >
                            <option value="" disabled>Select Profile</option>
                            {filteredProfiles.map((p:any) => <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}
                            <option value="__ADD_NEW_PROFILE__" className="font-bold text-blue-600 dark:text-blue-400">-- Add New Profile --</option>
                        </select>
                    </div>

                    <input type="number" placeholder="Cavities" value={form.cavities} onChange={e => setForm({...form, cavities: +e.target.value})} className={inputClass} />
                    <input type="number" placeholder="Output (Kg/Hr)" value={form.expectedOutputKgHr} onChange={e => setForm({...form, expectedOutputKgHr: +e.target.value})} className={inputClass} />
                    <input type="number" placeholder="Lifespan (m)" value={form.lifespanMeters} onChange={e => setForm({...form, lifespanMeters: +e.target.value})} className={inputClass} />
                    <select value={form.status} onChange={e => setForm({...form, status: e.target.value as any})} className={inputClass}>
                        <option value="ACTIVE">Active</option><option value="INACTIVE">Inactive</option><option value="MAINTENANCE">Maintenance</option>
                    </select>
                    <div className="col-span-2 flex justify-end gap-2 mt-2"><button type="button" onClick={onClose} className="px-4 py-2 border rounded">Cancel</button><button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded">Save</button></div>
                </form>
            </div>
            {/* FIX: Add the AddProfileModal as a sub-modal here */}
            <Portal>
                <AddProfileModal 
                    isOpen={isAddProfileSubModalOpen}
                    onClose={() => setIsAddProfileSubModalOpen(false)}
                    onAdd={(newProfileData) => {
                        const newProfile = addProfile(newProfileData); // Add and get the new profile
                        setNewlyCreatedProfileId(newProfile.id); // Store its ID in parent state
                        setIsAddProfileSubModalOpen(false); // Close sub-modal
                        addToast(`Profile "${newProfile.name}" added!`, 'success');
                        return newProfile; // Return for onAdd signature
                    }}
                    brands={brands}
                    addToast={addToast}
                />
            </Portal>
        </div>
    );
};

