// Helper to safely get storage, handling cases where localStorage is blocked (e.g. sandboxed iframes)
const getStorage = () => {
    try {
        if (typeof window !== 'undefined' && window.localStorage) {
            // Test if localStorage is actually accessible
            const testKey = '__storage_test__';
            window.localStorage.setItem(testKey, testKey);
            window.localStorage.removeItem(testKey);
            return window.localStorage;
        }
    } catch (e) {
        console.warn('LocalStorage access is restricted. Falling back to in-memory storage for this session.', e);
    }

    // Fallback in-memory storage
    const inMemoryStorage = new Map<string, string>();
    return {
        getItem: (key: string) => inMemoryStorage.get(key) ?? null,
        setItem: (key: string, value: string) => inMemoryStorage.set(key, value),
        removeItem: (key: string) => inMemoryStorage.delete(key),
    };
};

export const useStore = create<AppState>()(
    persist(
        (set, get) => ({
            // --- INITIAL STATE ---
            items: MOCK_ITEMS,
            inflowTransactions: MOCK_INFLOW_TRANSACTIONS,
            consumptionTransactions: MOCK_CONSUMPTION_TRANSACTIONS,
            formulas: MOCK_FORMULAS,
            reportCorrections: MOCK_REPORT_CORRECTIONS,
            profiles: MOCK_PROFILES,
            profileTransactions: MOCK_PROFILE_TRANSACTIONS,
            brands: ['Scraft', 'Smart', 'Eco'],
            customers: MOCK_CUSTOMERS,
            dies: MOCK_DIES,
            productionPlans: MOCK_PRODUCTION_PLANS,
            currentUser: null,
            companySettings: DEFAULT_COMPANY_SETTINGS,
            uiState: defaultUiState,

            // --- ACTIONS ---
            // Auth
            login: (user) => set({ currentUser: user }),
            logout: () => set({ currentUser: null }),

            // Global Settings
            updateCompanySettings: (settings) => set({ companySettings: settings }),

            // Items
            addItem: (itemData) => {
                const newItem: Item = { ...itemData, id: `item_${Date.now()}`, createdAt: new Date().toISOString() };
                set(state => ({ items: [newItem, ...state.items] }));
                return newItem;
            },
            updateItem: (updatedItem) => set(state => ({ items: state.items.map(i => i.id === updatedItem.id ? updatedItem : i) })),
            deleteItem: (itemId) => {
                const itemToDelete = get().items.find(i => i.id === itemId);
                if (!itemToDelete) return null;
                const now = new Date().toISOString();
                set(state => ({
                    items: state.items.map(i => i.id === itemId ? { ...i, deletedAt: now } : i),
                    inflowTransactions: state.inflowTransactions.map(tx => tx.itemId === itemId ? { ...tx, deletedAt: now } : tx),
                    consumptionTransactions: state.consumptionTransactions.map(tx => tx.itemId === itemId ? { ...tx, deletedAt: now } : tx),
                }));
                return itemToDelete.name;
            },

            // Inflow
            addInflowTransaction: (txData) => {
                const newTx: InflowTransaction = {
                    ...txData,
                    id: `txn_${Date.now()}`,
                    createdAt: new Date().toISOString(),
                    totalCost: txData.quantity * txData.unitCost,
                };
                set(state => ({ inflowTransactions: [newTx, ...state.inflowTransactions] }));
            },
            updateInflowTransaction: (updatedTx) => set(state => ({
                inflowTransactions: state.inflowTransactions.map(tx => tx.id === updatedTx.id ? updatedTx : tx),
            })),
            deleteInflowTransaction: (txId) => set(state => ({
                inflowTransactions: state.inflowTransactions.map(tx => tx.id === txId ? { ...tx, deletedAt: new Date().toISOString() } : tx),
            })),
            createItemAndInflow: (itemData, txData) => {
                const newItem = get().addItem(itemData);
                get().addInflowTransaction({ ...txData, itemId: newItem.id });
            },
            addMultipleInflowTransactions: (newTxnsData) => {
                let itemsToAdd: Item[] = [];
                const txnsToAdd: InflowTransaction[] = [];
                let currentItems = get().items;

                newTxnsData.forEach(txData => {
                    let item = currentItems.find(i => i.sku.toLowerCase() === txData.sku.toLowerCase() && !i.deletedAt);
                    if (!item && txData.name) {
                        const newItem: Item = {
                            id: `item_${Date.now()}_${txData.sku}`,
                            sku: txData.sku, name: txData.name, uom: 'unit',
                            reorderPoint: 0, costPrice: txData.unitCost,
                            createdAt: new Date().toISOString(),
                        };
                        itemsToAdd.push(newItem);
                        item = newItem;
                        currentItems = [newItem, ...currentItems];
                    }
                    if (item) {
                        const { sku, name, ...restOfTxData } = txData;
                        txnsToAdd.push({
                            id: `txn_${Date.now()}_${sku}`, itemId: item.id,
                            ...restOfTxData, totalCost: restOfTxData.quantity * restOfTxData.unitCost,
                            warehouseId: 'wh1', createdAt: new Date().toISOString(),
                        });
                    }
                });

                set(state => ({
                    items: [...itemsToAdd, ...state.items],
                    inflowTransactions: [...txnsToAdd, ...state.inflowTransactions],
                }));

                return { itemsAdded: itemsToAdd.length, txnsAdded: txnsToAdd.length };
            },

            // Consumption
            addMultipleConsumptionTransactions: (txnsData) => {
                const newTxs: ConsumptionTransaction[] = txnsData.map((tx, i) => ({
                    ...tx,
                    id: `con_${Date.now()}_${i}`,
                    createdAt: new Date().toISOString(),
                    type: tx.type || 'PROD'
                }));
                set(state => ({ consumptionTransactions: [...newTxs, ...state.consumptionTransactions] }));
                return newTxs.length;
            },
            updateConsumptionTransaction: (updatedTx) => set(state => ({
                consumptionTransactions: state.consumptionTransactions.map(tx => tx.id === updatedTx.id ? updatedTx : tx),
            })),
            deleteConsumptionTransaction: (txId) => set(state => ({
                consumptionTransactions: state.consumptionTransactions.map(tx => tx.id === txId ? { ...tx, deletedAt: new Date().toISOString() } : tx),
            })),

            // Formulas
            addFormula: (formulaData) => {
                const newFormula: Formula = { ...formulaData, id: `formula_${Date.now()}`, createdAt: new Date().toISOString() };
                set(state => ({ formulas: [newFormula, ...state.formulas] }));
            },
            updateFormula: (updatedFormula) => set(state => ({
                formulas: state.formulas.map(f => f.id === updatedFormula.id ? updatedFormula : f),
            })),
            deleteFormula: (formulaId) => set(state => ({
                formulas: state.formulas.map(f => f.id === formulaId ? { ...f, deletedAt: new Date().toISOString() } : f),
            })),

            // Profiles
            addProfile: (profileData) => {
                const newProfile: Profile = { ...profileData, id: `prof_${Date.now()}`, createdAt: new Date().toISOString() };
                set(state => ({
                    profiles: [...state.profiles, newProfile]
                }));
                return newProfile; // Return the newly created profile
            },
            updateProfile: (updatedProfile) => set(state => ({
                profiles: state.profiles.map(p => p.id === updatedProfile.id ? updatedProfile : p)
            })),
            deleteProfile: (id) => set(state => ({
                profiles: state.profiles.map(p => p.id === id ? { ...p, deletedAt: new Date().toISOString() } : p)
            })),
            addProfileTransaction: (txData) => {
                const newTx: ProfileTransaction = { ...txData, id: `pt_${Date.now()}`, createdAt: new Date().toISOString(), status: txData.type === 'QUOTATION' ? 'PENDING' : undefined };
                set(state => ({ profileTransactions: [...state.profileTransactions, newTx] }));
            },
            updateProfileTransaction: (updatedTx) => set(state => ({
                profileTransactions: state.profileTransactions.map(t => t.id === updatedTx.id ? updatedTx : t)
            })),
            deleteProfileTransaction: (id) => set(state => ({
                profileTransactions: state.profileTransactions.map(t => t.id === id ? { ...t, deletedAt: new Date().toISOString() } : t)
            })),
            resolveQuotation: (id, action) => {
                const quotation = get().profileTransactions.find(t => t.id === id);
                if (!quotation || quotation.type !== 'QUOTATION') return;

                if (action === 'CONFIRM') {
                    set(state => ({
                        profileTransactions: state.profileTransactions.map(t => t.id === id ? { ...t, status: 'COMPLETED' } : t)
                    }));

                    const dispatchTx: ProfileTransaction = { // Explicitly type dispatchTx
                        ...quotation,
                        id: `pt_${Date.now()}_dispatch`,
                        type: 'DISPATCH', // Ensure type is 'DISPATCH'
                        status: undefined, // Clear status for dispatch
                        createdAt: new Date().toISOString(),
                        refNo: quotation.refNo + '-D', // Distinguish dispatch ref
                    };
                    set(state => ({ profileTransactions: [...state.profileTransactions, dispatchTx] }));

                } else { // CANCEL
                    set(state => ({
                        profileTransactions: state.profileTransactions.map(t => t.id === id ? { ...t, status: 'CANCELLED' } : t)
                    }));
                }
            },

            // Brands
            addBrand: (brand) => set(state => ({ brands: [...state.brands, brand] })),
            updateBrand: (oldBrand, newBrand) => set(state => ({
                brands: state.brands.map(b => b === oldBrand ? newBrand : b),
                profiles: state.profiles.map(p => p.brand === oldBrand ? { ...p, brand: newBrand } : p),
                dies: state.dies.map(d => d.brand === oldBrand ? { ...d, brand: newBrand } : d)
            })),
            deleteBrand: (brand) => set(state => ({
                brands: state.brands.filter(b => b !== brand)
            })),

            // Customers
            addCustomer: (customer) => set(state => ({
                customers: [...state.customers, { ...customer, id: `cust_${Date.now()}`, createdAt: new Date().toISOString() }]
            })),
            updateCustomer: (customer) => set(state => ({
                customers: state.customers.map(c => c.id === customer.id ? customer : c)
            })),
            deleteCustomer: (id) => set(state => ({
                customers: state.customers.map(c => c.id === id ? { ...c, deletedAt: new Date().toISOString() } : c)
            })),

            // Dies & Planning
            addDie: (dieData) => {
                const profile = get().profiles.find(p => p.id === dieData.profileId);
                // FIX: Explicitly initialize processLog as an empty object for new dies
                const newDie: Die = { ...dieData, id: `die_${Date.now()}`, createdAt: new Date().toISOString(), brand: profile?.brand || '', processLog: {} };
                set(state => ({ dies: [...state.dies, newDie] }));
            },
            updateDie: (die) => {
                 const profile = get().profiles.find(p => p.id === die.profileId);
                 const updatedDie = { ...die, brand: profile?.brand || '' };
                 set(state => ({ dies: state.dies.map(d => d.id === die.id ? updatedDie : d) }))
            },
            deleteDie: (id) => set(state => ({ dies: state.dies.map(d => d.id === id ? { ...d, deletedAt: new Date().toISOString() } : d) })),
            addProductionPlan: (plan) => set(state => ({ productionPlans: [...state.productionPlans, { ...plan, id: `pp_${Date.now()}`, createdAt: new Date().toISOString() }] })),
            updateProductionPlan: (plan) => set(state => ({ productionPlans: state.productionPlans.map(p => p.id === plan.id ? plan : p) })),
            deleteProductionPlan: (id) => set(state => ({ productionPlans: state.productionPlans.map(p => p.id === id ? { ...p, deletedAt: new Date().toISOString() } : p) })),


            // Reports
            addOrUpdateReportCorrection: (correction) => set(state => {
                const existingIndex = state.reportCorrections.findIndex(c => c.itemId === correction.itemId && c.date === correction.date);
                const newCorrection = { ...correction, updatedAt: new Date().toISOString() };
                if (existingIndex > -1) {
                    const newCorrections = [...state.reportCorrections];
                    newCorrections[existingIndex] = newCorrection;
                    return { reportCorrections: newCorrections };
                }
                return { reportCorrections: [newCorrection, ...state.reportCorrections] };
            }),

            // Trash / Restore
            restoreItem: (itemId) => set(state => ({
                items: state.items.map(i => i.id === itemId ? { ...i, deletedAt: null } : i),
                inflowTransactions: state.inflowTransactions.map(tx => tx.itemId === itemId ? { ...tx, deletedAt: null } : tx),
                consumptionTransactions: state.consumptionTransactions.map(tx => tx.itemId === itemId ? { ...tx, deletedAt: null } : tx),
            })),
            restoreTransaction: (id, type) => {
                if (type === 'inflow') {
                    set(state => ({ inflowTransactions: state.inflowTransactions.map(tx => tx.id === id ? { ...tx, deletedAt: null } : tx) }));
                } else {
                    set(state => ({ consumptionTransactions: state.consumptionTransactions.map(tx => tx.id === id ? { ...tx, deletedAt: null } : tx) }));
                }
            },
