interface DieModalProps {
    isOpen: boolean;
    onClose: () => void;
    die: Die | null;
    profiles: Profile[];
    brands: string[];
    onSave: (data: Omit<Die, 'id' | 'createdAt' | 'brand'> | Die) => void;
    addToast: (message: string, type: ToastMessage['type']) => void;
    addProfile: (profile: Omit<Profile, 'id' | 'createdAt'>) => Profile;
    isAddProfileSubModalOpen: boolean; 
    setIsAddProfileSubModalOpen: (isOpen: boolean) => void; 
    setNewlyCreatedProfileId: (id: string | null) => void; 
    newlyCreatedProfileId: string | null; // Receive the ID
}

const DieModal: React.FC<DieModalProps> = ({ isOpen, onClose, die, profiles, brands, onSave, addToast, addProfile, isAddProfileSubModalOpen, setIsAddProfileSubModalOpen, setNewlyCreatedProfileId, newlyCreatedProfileId }) => {
    const [form, setForm] = useState({ dieNo: '', profileId: '', cavities: 1, expectedOutputKgHr: 100, lifespanMeters: 500000, status: 'ACTIVE' as 'ACTIVE' | 'INACTIVE' | 'MAINTENANCE' });
    const [modalBrandFilter, setModalBrandFilter] = useState('All');

    useEffect(() => {
        if (isOpen) {
            if (die) {
                setForm(die);
                setModalBrandFilter(die.brand || 'All'); // Set filter if editing existing die
            } else {
                setForm({ dieNo: '', profileId: '', cavities: 1, expectedOutputKgHr: 100, lifespanMeters: 500000, status: 'ACTIVE' });
            }
            // Clear newly created ID when opening a fresh modal
            setNewlyCreatedProfileId(null); 
        }
    }, [isOpen, die, setNewlyCreatedProfileId]); // Only depend on props that trigger form reset

    // FIX: This useEffect now correctly handles setting the profileId AFTER sub-modal closes
    useEffect(() => {
        if (!isAddProfileSubModalOpen && newlyCreatedProfileId) {
            setForm(prev => ({ ...prev, profileId: newlyCreatedProfileId }));
            setNewlyCreatedProfileId(null); // Clear it after use in parent
        }
    }, [isAddProfileSubModalOpen, newlyCreatedProfileId, setNewlyCreatedProfileId]);

    const filteredProfiles = useMemo(() => {
        if (modalBrandFilter === 'All') return profiles;
        return profiles.filter((p: any) => p.brand === modalBrandFilter);
    }, [profiles, modalBrandFilter]);

    if (!isOpen) return null;

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if(!form.profileId) {
            addToast('Please select a profile.', 'error');
            return;
        }
        // When saving, the brand is automatically set by the store.addDie/updateDie action
        onSave(form);
        onClose();
    };
    const inputClass = "w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 rounded-md text-sm dark:text-white outline-none";

    return (
         <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h3 className="font-bold mb-4 dark:text-white">{die ? 'Edit Die' : 'Add New Die'}</h3>
                <form onSubmit={handleSubmit} className="grid grid-cols-2 gap-4">
                    <input placeholder="Die No." value={form.dieNo} onChange={e => setForm({...form, dieNo: e.target.value})} className={inputClass} required />

                    <div className="col-span-1">
                        <select 
                            value={modalBrandFilter} 
                            onChange={e => setModalBrandFilter(e.target.value)} 
                            className={`${inputClass} mb-1 bg-gray-50 border-b-2 border-blue-200`}
                        >
                            <option value="All">Filter Profile by Brand</option>
                            {brands.map((b:string) => <option key={b} value={b}>{b}</option>)}
                        </select>
                         <select 
                            value={form.profileId} 
                            onChange={e => {
                                if (e.target.value === '__ADD_NEW_PROFILE__') {
                                    setIsAddProfileSubModalOpen(true);
                                } else {
                                    setForm(prev => ({...prev, profileId: e.target.value}));
                                }
                            }} 
                            className={inputClass} 
                            required
                        >
                            <option value="" disabled>Select Profile</option>
                            {filteredProfiles.map((p:any) => <option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}
                            <option value="__ADD_NEW_PROFILE__" className="font-bold text-blue-600 dark:text-blue-400">-- Add New Profile --</option>
                        </select>
                    </div>

                    <input type="number" placeholder="Cavities" value={form.cavities} onChange={e => setForm({...form, cavities: +e.target.value})} className={inputClass} />
                    <input type="number" placeholder="Output (Kg/Hr)" value={form.expectedOutputKgHr} onChange={e => setForm({...form, expectedOutputKgHr: +e.target.value})} className={inputClass} />
                    <input type="number" placeholder="Lifespan (m)" value={form.lifespanMeters} onChange={e => setForm({...form, lifespanMeters: +e.target.value})} className={inputClass} />
                    <select value={form.status} onChange={e => setForm({...form, status: e.target.value as any})} className={inputClass}>
                        <option value="ACTIVE">Active</option><option value="INACTIVE">Inactive</option><option value="MAINTENANCE">Maintenance</option>
                    </select>
                    <div className="col-span-2 flex justify-end gap-2 mt-2"><button type="button" onClick={onClose} className="px-4 py-2 border rounded">Cancel</button><button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded">Save</button></div>
                </form>
            </div>
            {/* FIX: Add the AddProfileModal as a sub-modal here */}
            <Portal>
                <AddProfileModal 
                    isOpen={isAddProfileSubModalOpen}
                    onClose={() => setIsAddProfileSubModalOpen(false)}
                    onAdd={(newProfileData) => {
                        const newProfile = addProfile(newProfileData); // Add and get the new profile
                        setNewlyCreatedProfileId(newProfile.id); // Store its ID in parent state
                        setIsAddProfileSubModalOpen(false); // Close sub-modal
                        addToast(`Profile "${newProfile.name}" added!`, 'success');
                        return newProfile; // Return for onAdd signature
                    }}
                    brands={brands}
                    addToast={addToast}
                />
            </Portal>
        </div>
    );
};

interface ProductionPlanModalProps {
